async function loadDashboard(){if(me?.role==='admin'){show('admin');return}const paid=hasPlan('intermediario');const [trips,purchases,alerts]=await Promise.all([api('/api/trips'),paid?api('/api/purchases'):Promise.resolve([]),paid?api('/api/alerts'):Promise.resolve([])]);if(paid){[$('#purchaseForm'),$('#alertForm')].forEach(f=>{if(f){f.querySelectorAll('input,select,button').forEach(x=>x.disabled=false);f.parentElement.querySelector('.planInlineLock')?.remove()}})}$('#hello').textContent=`Olá, ${me.name.split(' ')[0]}!`;$('#tripCount').textContent=trips.length;$('#brlTotal').textContent=money(purchases.reduce((a,p)=>a+p.total_brl,0));const sums={};purchases.forEach(p=>sums[p.currency]=(sums[p.currency]||0)+p.amount);$('#currencyTotal').textContent=Object.entries(sums).map(([c,v])=>`${fmt(v)} ${c}`).join(' · ')||'—';$('#purchaseTrip').innerHTML=trips.map(t=>`<option value="${t.id}">${esc(t.name)}</option>`).join('');$('#purchaseTrip').disabled=!trips.length;if(trips.length)$('#purchaseTrip').value=trips[0].id;$('#trips').innerHTML=trips.length?trips.map(t=>{const bought=purchases.filter(p=>p.trip_id===t.id&&p.currency===t.currency).reduce((a,p)=>a+p.amount,0),pct=t.target_amount?Math.min(100,bought/t.target_amount*100):0,days=t.start_date?Math.ceil((new Date(t.start_date+'T12:00:00')-new Date())/86400000):null;return `<article class="tripCard" onclick="openTrip(${t.id})"><div class="tripTop"><div><span class="eyebrow">${days!==null?(days>=0?`Faltam ${days} dias`:'Viagem realizada'):'Data a definir'}</span><h3>${esc(t.name)}</h3><p>${esc(t.destinations)||'Destinos a definir'}${t.shared?' · Viagem compartilhada':''}</p></div>${t.shared?'':`<button class="danger" onclick="event.stopPropagation();delTrip(${t.id})">Excluir</button>`}</div><div class="progress"><i style="width:${pct}%"></i></div><div class="tripMeta"><b>${fmt(bought)} / ${fmt(t.target_amount)} ${t.currency}</b><span>${pct.toFixed(0)}% da meta</span></div><button type="button" class="linkBtn" onclick="event.stopPropagation();openTrip(${t.id})">Abrir planejamento →</button></article>`}).join(''):'<div class="empty">Você ainda não cadastrou nenhuma viagem.</div>';$('#purchases').innerHTML=purchases.slice(0,6).map(p=>`<div class="listItem purchaseItem"><div><b>${fmt(p.amount)} ${p.currency}</b><span>${money(p.total_brl)} · VET ${p.vet.toFixed(4)} · ${esc(p.provider)||'Instituição não informada'} · ${brDate(p.purchased_at)}</span></div><div class="purchaseActions"><button type="button" class="editBtn" onclick="editPurchase(${p.id})">Editar</button><button type="button" class="removeBtn" onclick="delPurchase(${p.id})">Remover</button></div></div>`).join('')||'<div class="empty">Nenhuma compra registrada.</div>';$('#alerts').innerHTML=alerts.map(a=>`<div class="listItem"><b>${a.currency} ${a.kind==='below'?'abaixo':'acima'} de ${formatAlertBRL(a.threshold)}</b><button type="button" class="removeBtn alertRemoveBtn" onclick="delAlert(${a.id})">Remover</button></div>`).join('')||'<div class="empty">Nenhum alerta criado.</div>';if(!paid){const pf=$('#purchaseForm'),af=$('#alertForm');[pf,af].forEach(f=>{if(f){f.querySelectorAll('input,select,button').forEach(x=>x.disabled=true);if(!f.parentElement.querySelector('.planInlineLock'))f.insertAdjacentHTML('beforebegin','<button type="button" class="planInlineLock" onclick="upgradePrompt(\'intermediario\',\'Carteira, histórico e alertas cambiais\')">🔒 Disponível no Intermediário</button>')}});$('#purchases').innerHTML='<div class="empty">Carteira e histórico completos são liberados no plano Intermediário.</div>';$('#alerts').innerHTML='<div class="empty">Alertas cambiais são liberados no plano Intermediário.</div>'}}
function tripCompanions(t){const out=[];try{const a=JSON.parse(t.companions||'[]');if(Array.isArray(a))out.push(...a.filter(Boolean))}catch{}if(Array.isArray(t.companion_names))out.push(...t.companion_names.filter(Boolean));return [...new Set(out.map(x=>String(x).trim()).filter(Boolean))]}function renderCompanionFields(){const n=Math.max(1,Math.min(30,Number($('#tTravelers')?.value||1))),box=$('#companionFields');if(!box)return;const count=n-1;box.classList.toggle('hidden',count===0);box.innerHTML=count?`<h4>Nomes dos acompanhantes</h4>${Array.from({length:count},(_,i)=>`<label>Acompanhante ${i+1}<input class="companionName" maxlength="100" required placeholder="Nome do acompanhante"></label>`).join('')}`:''}const travelerCountInput=$('#tTravelers');if(travelerCountInput){travelerCountInput.addEventListener('input',renderCompanionFields);travelerCountInput.addEventListener('change',renderCompanionFields)}function splitSelector(names){if(!names.length)return '<div class="muted">Cadastre acompanhantes na viagem para dividir este item.</div>';return `<div class="splitPicker">${names.map((n,i)=>`<label><input type="checkbox" class="budgetSplit" value="${esc(n)}"> <span>${esc(n)}</span></label>`).join('')}</div>`}async function openTrip(id,tab='overview',opts={}){currentTrip=await api('/api/trips/'+id);if(hasPlan('pro'))loadGoogleMaps().catch(()=>{});const min=requiredPlanForTab(tab);currentTab=(min&&!hasPlan(min))?'overview':tab;renderTrip();show('tripDetail',{remember:false});if(opts.remember!==false)saveView('tripDetail',{tripId:Number(id),tab:currentTab})}async function refreshTrip(){const tab=currentTab;currentTrip=await api('/api/trips/'+currentTrip.trip.id);currentTab=tab==='central'?'overview':tab;renderTrip()}function renderTrip(){const d=currentTrip,t=d.trip,bought=d.purchases.filter(p=>p.currency===t.currency).reduce((a,p)=>a+p.amount,0),pct=t.target_amount?Math.min(100,bought/t.target_amount*100):0;$('#tripHero').innerHTML=`<div class="tripHero"><div><span class="eyebrow">${esc(t.destinations)}</span><h1>${esc(t.name)}</h1><p>${brDate(t.start_date)} → ${t.end_date?brDate(t.end_date):'—'} · ${t.travelers} viajante(s) · Perfil ${esc(t.profile)}</p></div><div class="goal"><span>Meta cambial</span><strong>${fmt(bought)} / ${fmt(t.target_amount)} ${t.currency}</strong><div class="progress"><i style="width:${pct}%"></i></div><small>${pct.toFixed(0)}% concluído</small><button type="button" class="linkBtn personalGoalBtn" onclick="openPersonalGoal()">${Number(t.target_amount)>0?'Alterar minha meta':'Definir minha meta'}</button></div></div>`;updateTripNav();Promise.resolve(renderPanel()).then(applyTripPermissionUi).catch(e=>console.error('Falha ao renderizar viagem',e))}function openPersonalGoal(){const t=currentTrip?.trip;if(!t)return;$('#personalGoalCurrency').textContent=t.currency;$('#personalGoalAmount').value=Number(t.target_amount)||0;$('#personalGoalMsg').textContent='';$('#personalGoalDialog').showModal()}window.openPersonalGoal=openPersonalGoal;$('#personalGoalClose').onclick=()=>$('#personalGoalDialog').close();$('#personalGoalForm').onsubmit=async e=>{e.preventDefault();try{await api('/api/trips/'+currentTrip.trip.id+'/personal-goal',{method:'PATCH',body:JSON.stringify({target_amount:$('#personalGoalAmount').value})});$('#personalGoalDialog').close();await refreshTrip()}catch(err){$('#personalGoalMsg').textContent=err.message}};function updateTripNav(){applyPlanLocks();$$('.tripTabs [data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===currentTab));const groups={planning:['budget','itinerary','reservations','checklist'],discover:['map','explore'],organize:['documents','expenses','travelers']};$$('.tripGroupBtn').forEach(b=>b.classList.toggle('active',(groups[b.dataset.group]||[]).includes(currentTab)))}$$('.tripTabs [data-tab]').forEach(b=>b.onclick=async()=>{const min=requiredPlanForTab(b.dataset.tab);if(min&&!hasPlan(min)){upgradePrompt(min,b.dataset.tab==='assistant'?'Assistente de viagem com IA':b.dataset.tab==='explore'?'Explorar com Google Places':b.dataset.tab==='map'?'Mapa inteligente':b.dataset.tab==='documents'?'Documentos privados':'Divisão de despesas');return}currentTab=b.dataset.tab;if(currentTrip?.trip?.id)saveView('tripDetail',{tripId:Number(currentTrip.trip.id),tab:currentTab});updateTripNav();$$('.tripTabGroup').forEach(g=>g.classList.remove('open'));const panel=$('#tripPanel');if(['map','explore','documents','expenses','travelers','assistant','central'].includes(currentTab))panel.innerHTML='<div class="empty">Carregando…</div>';try{await renderPanel();applyTripPermissionUi()}catch(e){console.error('Falha ao abrir aba',currentTab,e);panel.innerHTML=`<div class="empty errorPanel"><b>Não foi possível abrir esta área.</b><span>${esc(e.message||'Erro inesperado.')}</span><button type="button" class="primary" id="retryTab">Tentar novamente</button></div>`;const r=$('#retryTab');if(r)r.onclick=()=>renderTrip()}});$$('.tripGroupBtn').forEach(b=>b.onclick=e=>{e.stopPropagation();const g=b.closest('.tripTabGroup'),was=g.classList.contains('open');$$('.tripTabGroup').forEach(x=>x.classList.remove('open'));if(!was)g.classList.add('open')});document.addEventListener('click',e=>{if(!e.target.closest('.tripTabGroup'))$$('.tripTabGroup').forEach(g=>g.classList.remove('open'))});function tripPlaces(t){return String(t.destinations||'').split(/[,;\n]+/).map(x=>x.trim()).filter(Boolean)}function placeOptions(t,selected=''){const a=tripPlaces(t);return a.map(x=>`<option value="${esc(x)}" ${x===selected?'selected':''}>${esc(x)}</option>`).join('')}function formatFlightTime(v){if(!v)return 'Horário não informado';try{const d=new Date(v);if(Number.isNaN(d.getTime()))return String(v).replace('T',' ');return new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'}).format(d)}catch{return String(v)}}function brDate(v){if(!v)return 'Sem data';const [y,m,d]=String(v).split('-');return d&&m&&y?`${d}/${m}/${y}`:v}function bulletNotes(v){return String(v||'').split(/\r?\n/).map(x=>x.trim()).filter(Boolean).map(x=>`• ${esc(x)}`).join(' &nbsp; ')}async function assignReservationEmail(id,tripId){try{await api('/api/email/reservas/'+id+'/assign',{method:'POST',body:JSON.stringify({trip_id:tripId})});await refreshTrip()}catch(e){alert(e.message)}}window.assignReservationEmail=assignReservationEmail;function daysUntilDate(v){if(!v)return null;const d=new Date(String(v).slice(0,10)+'T12:00:00'),n=new Date();n.setHours(12,0,0,0);return Number.isNaN(d.getTime())?null:Math.ceil((d-n)/86400000)}
function nextStepCards(d,pending=[]){const t=d.trip,cards=[];for(const x of d.itinerary||[]){const days=daysUntilDate(x.item_date);if(days===null||days<0)continue;const text=`${x.title||''} ${x.location||''}`;let icon='📍',label=days===0?'Acontece hoje':days===1?'Acontece amanhã':`Em ${days} dias`;if(/voo|flight|aeroporto/i.test(text)){icon='✈️';label=days===0?'Voo hoje':days===1?'Voo amanhã':`Voo em ${days} dias`}else if(/hotel|check.?in|hosped/i.test(text)){icon='🏨';label=days===0?'Check-in hoje':days===1?'Check-in amanhã':`Check-in em ${days} dias`}cards.push({priority:days<=1?1:3,days,icon,title:label,detail:[x.title,x.location].filter(Boolean).join(' · '),meta:brDate(x.item_date),submeta:days===0?'Hoje':days===1?'Amanhã':`Em ${days} dias`,tab:'itinerary'});}
const todo=(d.checklist||[]).filter(x=>!x.done).length;if(todo)cards.push({priority:2,days:999,icon:'✓',title:`${todo} ${todo===1?'item pendente':'itens pendentes'} no checklist`,detail:'Confira o que ainda precisa ser resolvido.',meta:'Em aberto',tab:'checklist'});
const bought=(d.purchases||[]).filter(p=>p.currency===t.currency).reduce((a,p)=>a+(Number(p.amount)||0),0),missing=Math.max(0,(Number(t.target_amount)||0)-bought);if(missing>0)cards.push({priority:4,days:999,icon:'€',title:`${fmt(missing)} ${t.currency} ainda faltam para sua meta`,detail:`${fmt(bought)} de ${fmt(Number(t.target_amount)||0)} ${t.currency} acumulados.`,meta:'Meta cambial',tab:'goal'});
const unconfirmed=(d.reservations||[]).filter(r=>!String(r.confirmation||'').trim());if(unconfirmed.length)cards.push({priority:2,days:999,icon:'⚠',title:`${unconfirmed.length} ${unconfirmed.length===1?'reserva sem confirmação':'reservas sem confirmação'}`,detail:unconfirmed[0].provider||'Revise os dados das reservas.',meta:'Revisar',tab:'reservations'});
const reviews=pending.filter(x=>x.processing_status==='pending_review'&&Number(x.trip_id)===Number(t.id));if(reviews.length)cards.push({priority:0,days:0,icon:'!',title:`${reviews.length} ${reviews.length===1?'reserva aguardando revisão':'reservas aguardando revisão'}`,detail:'Confirme os dados antes de cadastrar.',meta:'Revisar agora',tab:'reservations'});
return cards.sort((a,b)=>a.priority-b.priority||a.days-b.days)}
function openCurrencyPurchaseForTrip(){const t=currentTrip?.trip;if(!t)return;show('dashboard');setTimeout(()=>{const trip=$('#purchaseTrip'),currency=$('#pCurrency'),amount=$('#pAmount');if(trip)trip.value=String(t.id);if(currency)currency.value=t.currency;const form=$('#purchaseForm');form?.scrollIntoView({behavior:'smooth',block:'center'});setTimeout(()=>amount?.focus(),350)},150)}window.openCurrencyPurchaseForTrip=openCurrencyPurchaseForTrip;function openNextStep(tab){if(tab==='goal'){openCurrencyPurchaseForTrip();return}currentTab=tab;updateTripNav();renderPanel().then(applyTripPermissionUi);saveView('tripDetail',{tripId:Number(currentTrip.trip.id),tab:currentTab})}window.openNextStep=openNextStep;function showAllNextSteps(){const list=document.querySelector('.smartNextSteps .nextStepsList'),btn=document.querySelector('.smartNextSteps .nextStepsAll');if(!list)return;list.querySelectorAll('.nextStepItem[data-extra="1"]').forEach(el=>el.hidden=false);if(btn){btn.textContent='Mostrando todos';btn.disabled=true;btn.classList.add('isExpanded')}}window.showAllNextSteps=showAllNextSteps;
async function reviewReservationEmail(id){const x=(window._pendingReservationEmails||[]).find(v=>Number(v.id)===Number(id));if(!x)return;const p=x.parsed||{},kind=prompt('Tipo da reserva (Hotel, Voo, Trem, Seguro, Atração ou Outro):',p.kind||'Outro');if(kind===null)return;const provider=prompt('Fornecedor/estabelecimento:',p.provider||'');if(provider===null)return;const confirmation=prompt('Código/localizador (pode ficar vazio):',p.confirmation||'');if(confirmation===null)return;const amount=prompt('Valor em R$ (0 se não informado):',String(p.amount_brl||0));if(amount===null)return;await api(`/api/email/reservas/${id}/review`,{method:'POST',body:JSON.stringify({trip_id:currentTrip.trip.id,kind,provider,confirmation,amount_brl:amount})});await refreshTrip()}window.reviewReservationEmail=reviewReservationEmail;
async function discardReservationEmail(id){if(!confirm('Descartar esta importação?'))return;await api(`/api/email/reservas/${id}/discard`,{method:'POST',body:'{}'});await refreshTrip()}window.discardReservationEmail=discardReservationEmail;
function tripDateRange(start,end){const out=[];if(!/^\d{4}-\d{2}-\d{2}$/.test(start||'')||!/^\d{4}-\d{2}-\d{2}$/.test(end||''))return out;let d=new Date(start+'T12:00:00'),last=new Date(end+'T12:00:00');for(let guard=0;d<=last&&guard<370;guard++,d.setDate(d.getDate()+1))out.push(d.toISOString().slice(0,10));return out}
function packingWeatherIcon(code){code=Number(code);if(code===0)return '☀️';if([1,2].includes(code))return '🌤️';if(code===3)return '☁️';if([45,48].includes(code))return '🌫️';if([51,53,55,56,57,61,63,65,66,67,80,81,82].includes(code))return '🌧️';if([71,73,75,77,85,86].includes(code))return '🌨️';if([95,96,99].includes(code))return '⛈️';return '—'}
