async function addTripItem(e,type,data){e.preventDefault();if(!requireTripEdit())return;await api('/api/'+type,{method:'POST',body:JSON.stringify({trip_id:currentTrip.trip.id,...data})});await refreshTrip()}async function delItem(type,id){if(!requireTripEdit())return;await api(`/api/${type}/${id}`,{method:'DELETE'});await refreshTrip()}async function toggleCheck(id,done){if(!requireTripEdit())return;await api('/api/checklist/'+id,{method:'PATCH',body:JSON.stringify({done})});await refreshTrip()}
async function toolRows(type){return api(`/api/trip-tools?trip_id=${currentTrip.trip.id}&type=${type}`)}async function addTool(type,data){if(!requireTripEdit())return;await api('/api/trip-tools',{method:'POST',body:JSON.stringify({trip_id:currentTrip.trip.id,type,data})});renderAdvancedPanel(currentTab)}async function delTool(id){if(currentTab!=='documents'&&!requireTripEdit())return;await api('/api/trip-tools/'+id,{method:'DELETE'});renderAdvancedPanel(currentTab)}
function editField(label,control){return `<label>${label}${control}</label>`}
function openEditModal(title,fields,onSave,saveLabel='Salvar alterações'){const dlg=$('#editDialog'),form=$('#editForm'),submit=form.querySelector('button[type=submit]');$('#editTitle').textContent=title;$('#editFields').innerHTML=fields;$('#editMsg').textContent='';if(submit)submit.textContent=saveLabel;form.onsubmit=async e=>{e.preventDefault();try{await onSave();dlg.close()}catch(err){$('#editMsg').textContent=err.message}};dlg.showModal()}
