function assistantPrice(level){const m={PRICE_LEVEL_FREE:'$',PRICE_LEVEL_INEXPENSIVE:'$',PRICE_LEVEL_MODERATE:'$$',PRICE_LEVEL_EXPENSIVE:'$$$',PRICE_LEVEL_VERY_EXPENSIVE:'$$$$'};return m[level]||''}
function assistantDistance(m){m=Number(m);if(!Number.isFinite(m))return '';return m<1000?`${Math.round(m)} m`:`${(m/1000).toFixed(1).replace('.',',')} km`}
function assistantPlaceCards(ui){if(!ui||!['nearby_restaurants','nearby_places'].includes(ui.type)||!Array.isArray(ui.places)||!ui.places.length)return '';const ref=ui.reference||{},restaurant=ui.type==='nearby_restaurants';return `<div class="assistantPlaces"><div class="assistantPlacesHead"><div><span class="eyebrow">Perto de ${esc(ref.name||'sua hospedagem')}</span><p>${esc(ref.address||'')}</p></div></div><div class="assistantRestaurantList">${ui.places.map((r,i)=>{const price=assistantPrice(r.price_level),dist=assistantDistance(r.distance_meters);return `<article class="assistantRestaurantCard"><div class="assistantRestaurantInfo"><div class="assistantRestaurantTop"><span class="assistantPlaceNumber">${i+1}</span><div><h4>${esc(r.name)}</h4><p class="assistantCuisine">${esc(r.category||(restaurant?'Restaurante':'Local'))}</p></div></div><div class="assistantPlaceMeta">${r.rating?`<span class="assistantRating"><span aria-hidden="true">★</span> ${Number(r.rating).toFixed(1).replace('.',',')}${r.reviews?` <small>(${Number(r.reviews).toLocaleString('pt-BR')})</small>`:''}</span>`:''}${price?`<span class="assistantPrice">${price}</span>`:''}${dist?`<span>${esc(dist)} da hospedagem</span>`:''}</div><p class="assistantAddress">${esc(r.address||'Endereço não informado')}</p><div class="assistantCardActions"><button type="button" class="assistantSavePlace" data-place="${i}">Salvar lugar</button><button type="button" class="assistantAddRoute" data-place="${i}">Adicionar ao roteiro</button>${r.map_url?`<a class="assistantMapLink" href="${esc(r.map_url)}" target="_blank" rel="noopener">Abrir no Google Maps</a>`:''}</div></div><div class="assistantRestaurantPhoto">${r.image?`<img src="${esc(r.image)}" alt="Foto de ${esc(r.name)}" loading="lazy">`:`<div class="assistantPhotoFallback" aria-hidden="true">📍</div>`}</div></article>`}).join('')}</div><div class="assistantMapWrap"><div class="assistantMapTitle"><h4>${restaurant?'Restaurantes':'Sugestões'} no mapa</h4><p>Veja a posição de cada opção em relação à hospedagem.</p></div><div class="assistantPlacesMap"><div class="mapLoading">Carregando mapa…</div></div></div></div>`}
function weatherIcon(code){code=Number(code);if(code===0)return '☀️';if([1,2].includes(code))return '🌤️';if(code===3)return '☁️';if([45,48].includes(code))return '🌫️';if([51,53,55,56,57,61,63,65,66,67,80,81,82].includes(code))return '🌧️';if([71,73,75,77,85,86].includes(code))return '🌨️';if([95,96,99].includes(code))return '⛈️';return '🌤️'}
function assistantWeatherCard(ui){if(ui?.type!=='weather'||!ui.weather)return '';const w=ui.weather,c=w.current||{},days=w.days||[],rain=Number(c.rain||c.precipitation||0),today=days[0]||{};return `<div class="assistantWeather"><div class="weatherNow"><div class="weatherIcon">${weatherIcon(c.weather_code)}</div><div><span class="eyebrow">${esc(w.place?.name||'Previsão do tempo')}</span><div class="weatherTemp">${Math.round(Number(c.temperature_2m||0))}°C</div><p>Sensação de ${Math.round(Number(c.apparent_temperature||0))}°C · Umidade ${Math.round(Number(c.relative_humidity_2m||0))}% · Vento ${Math.round(Number(c.wind_speed_10m||0))} km/h</p></div><div class="weatherRain"><span>Chuva hoje</span><strong>${Math.round(Number(today.rain_probability||0))}%</strong><small>${rain>0?`${rain.toFixed(1).replace('.',',')} mm agora`:'sem chuva agora'}</small></div></div><div class="weatherDays">${days.map(d=>`<div class="weatherDay"><span>${new Date(d.date+'T12:00:00').toLocaleDateString('pt-BR',{weekday:'short'}).replace('.','')}</span><b>${weatherIcon(d.weather_code)}</b><small>${Math.round(Number(d.max))}° <i>${Math.round(Number(d.min))}°</i></small><em>💧 ${Math.round(Number(d.rain_probability||0))}%</em></div>`).join('')}</div><p class="weatherSource">Previsão meteorológica: Open-Meteo · horários no fuso local do destino.</p></div>`}
function assistantVisual(ui){return assistantPlaceCards(ui)+assistantProposalCard(ui)||assistantWeatherCard(ui)}

async function renderAssistantPlacesMap(ui,root=document){const el=root.querySelector('.assistantPlacesMap');if(!el||!ui?.places?.length)return;try{await loadGoogleMaps();const ref=ui.reference?.location,points=ui.places.filter(x=>x.location);if(!ref&&!points.length){el.innerHTML='<div class="empty">Localização indisponível para o mapa.</div>';return}const center=ref?{lat:Number(ref.latitude),lng:Number(ref.longitude)}:{lat:Number(points[0].location.latitude),lng:Number(points[0].location.longitude)};const map=new google.maps.Map(el,{center,zoom:14,mapTypeControl:false,streetViewControl:false,fullscreenControl:true});const bounds=new google.maps.LatLngBounds();if(ref){const pos={lat:Number(ref.latitude),lng:Number(ref.longitude)};new google.maps.Marker({map,position:pos,title:ui.reference?.name||'Hospedagem',label:'H'});bounds.extend(pos)}points.forEach((r,i)=>{const pos={lat:Number(r.location.latitude),lng:Number(r.location.longitude)};const marker=new google.maps.Marker({map,position:pos,title:r.name,label:String(i+1)});if(r.map_url)marker.addListener('click',()=>window.open(r.map_url,'_blank','noopener'));bounds.extend(pos)});if((ref?1:0)+points.length>1)map.fitBounds(bounds,52)}catch(e){console.error('Mapa do Assistente',e);el.innerHTML='<div class="empty">Não foi possível carregar o mapa agora.</div>'}}
async function renderAdvancedPanel(tab){const box=$('#tripPanel'),t=currentTrip.trip;if(tab==='map'){const days=itineraryDays();let savedChoices=[];try{savedChoices=await toolRows('route_choice')}catch(e){console.warn('Escolhas de rota indisponíveis',e)}const opts=days.map(([d,items])=>`<option value="${esc(d)}">${d==='sem-data'?'Sem data':brDate(d)} · ${esc(items[0]?.title||items[0]?.location||'Roteiro')}</option>`).join('');box.innerHTML=`<div class="mapDayToolbar card"><label>Dia do roteiro<select id="mapDay"><option value="all">Todos os dias</option>${opts}</select></label><label>Transporte<select id="routeMode"><option value="WALK">A pé</option><option value="DRIVE">Carro</option><option value="BICYCLE">Bicicleta</option><option value="TRANSIT">Transporte público</option></select></label><button class="primary" id="buildDayRoute">Montar roteiro visual</button></div><div class="mapLayout"><div class="card"><h3>Mapa da viagem</h3><div id="tripGoogleMap" class="tripMap"><div class="mapLoading">Carregando Google Maps…</div></div><p id="mapStatus" class="muted">Escolha um dia para transformar as paradas do Roteiro em um trajeto visual.</p><div id="routeSummary"></div></div><div><h3>Paradas do dia</h3><div id="dayStops"><div class="empty">Selecione um dia e clique em “Montar roteiro visual”.</div></div></div></div>`;await initTripGoogleMap([],t);const build=async()=>{const chosen=$('#mapDay').value,mode=$('#routeMode').value,status=$('#mapStatus'),list=$('#dayStops'),summary=$('#routeSummary');summary.innerHTML='';status.textContent='Localizando as paradas no Google Places…';const items=chosen==='all'?currentTrip.itinerary:(days.find(([d])=>d===chosen)?.[1]||[]);const resolved=await resolveDayStops(items,t);for(let i=0;i<resolved.stops.length;i++){const s=resolved.stops[i];if(!s.ambiguous)continue;const saved=savedChoices.find(x=>x.data?.date===chosen&&x.data?.prompt===s.label);if(saved?.data?.address)resolved.stops[i]={label:saved.data.label,address:saved.data.address,location:{lat:Number(saved.data.lat),lng:Number(saved.data.lng)}}}window.ihResolvedStops=resolved.stops;const renderList=()=>{let order=0;list.innerHTML=resolved.stops.map((s,i)=>{if(s.ambiguous)return `<div class="listItem ambiguity"><div><b>Escolha o local</b><span>${esc(s.label)}</span><select class="ambiguityChoice" data-i="${i}"><option value="">Selecione…</option>${s.choices.map((c,j)=>`<option value="${j}">${esc(c.label)} · ${esc(c.address)}</option>`).join('')}</select></div></div>`;order++;return `<div class="listItem"><div class="routeNumber">${order}</div><div><b>${esc(s.label)}</b><span>${esc(s.address)}</span></div></div>`}).join('')+(resolved.unresolved.length?`<div class="empty">Não localizados automaticamente: ${esc(resolved.unresolved.join(', '))}</div>`:'')||'<div class="empty">Nenhuma parada identificada neste dia.</div>';list.querySelectorAll('.ambiguityChoice').forEach(sel=>sel.onchange=()=>{const i=Number(sel.dataset.i),j=Number(sel.value);if(!Number.isFinite(j))return;const prompt=resolved.stops[i].label,c=resolved.stops[i].choices[j];resolved.stops[i]={label:c.label,address:c.address,location:c.location};const lat=typeof c.location?.lat==='function'?c.location.lat():c.location?.lat,lng=typeof c.location?.lng==='function'?c.location.lng():c.location?.lng;api('/api/trip-tools',{method:'POST',body:JSON.stringify({trip_id:t.id,type:'route_choice',data:{date:chosen,prompt,label:c.label,address:c.address,lat,lng}})}).then(x=>savedChoices.unshift({data:{date:chosen,prompt,label:c.label,address:c.address,lat,lng}})).catch(e=>console.warn('Não foi possível salvar escolha',e));renderList();drawDayMarkers(resolved.stops)})};renderList();await drawDayMarkers(resolved.stops);const ready=resolved.stops.filter(s=>!s.ambiguous&&s.address);const pending=resolved.stops.filter(s=>s.ambiguous).length;if(pending){status.textContent=`${ready.length} parada(s) localizada(s). Escolha ${pending} local(is) genérico(s) antes de calcular a rota.`;return}if(ready.length<2){status.textContent='Não há pelo menos duas paradas localizadas para montar a rota.';return}status.textContent=`${ready.length} paradas localizadas. Calculando distâncias e trajeto real…`;try{const r=await api('/api/routes/compute',{method:'POST',body:JSON.stringify({trip_id:t.id,mode,points:ready.map(x=>({label:x.label,address:x.address}))})});await drawGoogleRoute(r);const km=r.distance_meters/1000,mins=Math.round(r.duration_seconds/60);summary.innerHTML=`<div class="routeResult"><b>${fmt(km,1)} km · ${formatRouteDuration(mins)}</b><span>${esc(r.points.join(' → '))}</span><small>Google Places + Google Routes</small></div>`;status.textContent=`Roteiro visual pronto: ${ready.length} paradas na ordem do dia.`}catch(e){summary.innerHTML=`<div class="empty errorPanel">${esc(e.message)}</div>`;status.textContent='As paradas foram localizadas, mas a rota não pôde ser calculada.'}};$('#buildDayRoute').onclick=()=>build().catch(e=>{$('#mapStatus').textContent=e.message});if(days.length){$('#mapDay').value=days[0][0];build().catch(e=>{$('#mapStatus').textContent=e.message})}return}
if(tab==='explore'){box.innerHTML=`<div class="card"><h3>Explorar lugares</h3><p>Pesquise lugares reais no Google Places dentro do destino selecionado e adicione diretamente ao planejamento da viagem.</p><div class="row"><label>Destino<select id="exDest">${placeOptions(t)}</select></label><label>O que procura?<input id="exQuery" placeholder="restaurantes, museus, atrações..."></label></div><button class="primary" id="exSearch">Pesquisar</button></div><div id="exploreResults"></div>`;
const ensureExploreDialog=()=>{let d=$('#explorePlaceDialog');if(d)return d;d=document.createElement('dialog');d.id='explorePlaceDialog';d.className='explorePlaceDialog';d.innerHTML=`<div class="modal explorePlaceModal"><button class="close" type="button" id="explorePlaceClose" aria-label="Fechar">×</button><div id="explorePlaceBody"></div></div>`;document.body.appendChild(d);d.querySelector('#explorePlaceClose').onclick=()=>d.close();d.addEventListener('click',e=>{if(e.target===d)d.close()});return d};
const showPlaceMap=async x=>{const d=ensureExploreDialog(),body=d.querySelector('#explorePlaceBody');body.innerHTML=`<h2>${esc(x.displayName||'Local')}</h2><p class="muted">${esc(x.formattedAddress||'')}</p><div id="explorePlaceMap" class="explorePlaceMap"><div class="mapLoading">Carregando mapa…</div></div>`;if(!d.open)d.showModal();try{await loadGoogleMaps();const pos=x.location;if(!pos)throw new Error('Localização indisponível para este lugar.');const map=new google.maps.Map($('#explorePlaceMap'),{center:pos,zoom:16,mapTypeControl:false,streetViewControl:false,fullscreenControl:false});new google.maps.Marker({position:pos,map,title:x.displayName||''})}catch(e){$('#explorePlaceMap').innerHTML=`<div class="empty">${esc(e.message)}</div>`}};
const planPlace=x=>{const d=ensureExploreDialog(),body=d.querySelector('#explorePlaceBody'),min=currentTrip.trip.start_date||'',max=currentTrip.trip.end_date||'';body.innerHTML=`<h2>${esc(x.displayName||'Adicionar lugar')}</h2><p class="muted">${esc(x.formattedAddress||'')}</p><p>Escolha como deseja guardar este lugar na viagem.</p><label>Data do roteiro<input id="explorePlanDate" type="date" ${min?`min="${esc(min)}"`:''} ${max?`max="${esc(max)}"`:''}></label><label>Horário <span class="muted">(opcional)</span><input id="explorePlanTime" type="time"></label><label>Observações <span class="muted">(opcional)</span><textarea id="explorePlanNotes" rows="3" placeholder="Ex.: reservar mesa, comprar ingresso..."></textarea></label><p id="explorePlanMsg" class="error"></p><div class="explorePlanActions"><button type="button" class="quoteBtn" id="exploreSaveOnly">Salvar para depois</button><button type="button" class="primary" id="exploreAddItinerary">Adicionar ao roteiro</button></div>`;if(!d.open)d.showModal();const placeCountry=()=>{const c=x.addressComponents?.find(a=>(a.types||[]).includes('country'));return c?.longText||c?.shortText||$('#exDest')?.value||''};const payload=()=>({placeId:x.id||'',name:x.displayName||'',country:placeCountry(),address:x.formattedAddress||'',mapUrl:x.googleMapsURI||''});$('#exploreSaveOnly').onclick=async()=>{const btn=$('#exploreSaveOnly');btn.disabled=true;try{await api('/api/trip-tools',{method:'POST',body:JSON.stringify({trip_id:currentTrip.trip.id,type:'place',data:payload()})});btn.textContent='Salvo ✓';setTimeout(()=>d.close(),500)}catch(e){$('#explorePlanMsg').textContent=e.message;btn.disabled=false}};$('#exploreAddItinerary').onclick=async()=>{const date=$('#explorePlanDate').value;if(!date){$('#explorePlanMsg').textContent='Selecione a data em que deseja visitar este lugar.';return}const btn=$('#exploreAddItinerary');btn.disabled=true;try{await api('/api/itinerary',{method:'POST',body:JSON.stringify({trip_id:currentTrip.trip.id,item_date:date,item_time:$('#explorePlanTime').value||'',title:placeCountry()||x.primaryTypeDisplayName||'Passeio',location:x.displayName||'',notes:$('#explorePlanNotes').value||x.formattedAddress||''})});await api('/api/trip-tools',{method:'POST',body:JSON.stringify({trip_id:currentTrip.trip.id,type:'place',data:{...payload(),itineraryDate:date}})}).catch(()=>{});btn.textContent='Adicionado ✓';setTimeout(async()=>{d.close();await refreshTrip()},500)}catch(e){$('#explorePlanMsg').textContent=e.message;btn.disabled=false}}};
$('#exSearch').onclick=async()=>{const dest=$('#exDest').value,q=$('#exQuery').value.trim()||'atrações';const out=$('#exploreResults');out.innerHTML='<div class="empty">Pesquisando no Google Places…</div>';try{await loadGoogleMaps();const {Place}=await google.maps.importLibrary('places');const regionCodes={'Portugal':'pt','Espanha':'es','Itália':'it','Suíça':'ch','França':'fr','Alemanha':'de','Reino Unido':'gb','Estados Unidos':'us','Brasil':'br','Grécia':'gr','Turquia':'tr','Albânia':'al'};const request={textQuery:`${q} em ${dest}`,fields:['id','displayName','formattedAddress','addressComponents','rating','userRatingCount','googleMapsURI','primaryTypeDisplayName','photos','location'],maxResultCount:20,language:'pt-BR'};if(regionCodes[dest])request.region=regionCodes[dest];const r=await Place.searchByText(request);const norm=v=>String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();const wanted=norm(dest);const rows=(r.places||[]).filter(x=>{const country=x.addressComponents?.find(c=>(c.types||[]).includes('country'));const countryName=country?.longText||country?.shortText||'';return norm(countryName)===wanted||norm(x.formattedAddress).includes(wanted)}).slice(0,12);if(!rows.length){out.innerHTML=`<div class="empty">Nenhum resultado confirmado dentro de ${esc(dest)} para essa busca. Tente outro termo.</div>`;return}out.innerHTML='<div class="exploreGrid">'+rows.map((x,i)=>{let image='';try{image=x.photos?.[0]?.getURI?x.photos[0].getURI({maxWidth:800}):''}catch{}const title=x.displayName||'';const cat=x.primaryTypeDisplayName||'Local';return `<article class="card placeCard">${image?`<img src="${esc(image)}" alt="${esc(title)}" loading="lazy">`:''}<h3>${esc(title)}</h3><p>${esc(cat)} · ${esc(x.formattedAddress||'Endereço não informado')}</p>${x.rating?`<p class="muted">★ ${fmt(x.rating,1)} · ${fmt(x.userRatingCount||0,0)} avaliações no Google</p>`:''}<div class="actions"><button type="button" class="quoteBtn viewPlaceMap" data-i="${i}">Ver mapa</button><button type="button" class="primary planPlace" data-i="${i}">+ Salvar</button></div></article>`}).join('')+'</div>';out.querySelectorAll('.viewPlaceMap').forEach(b=>b.onclick=()=>showPlaceMap(rows[Number(b.dataset.i)]));out.querySelectorAll('.planPlace').forEach(b=>b.onclick=()=>planPlace(rows[Number(b.dataset.i)]))}catch(e){console.error(e);out.innerHTML=`<div class="empty">${esc(e.message||'Não foi possível consultar o Google Places agora.')}</div>`}};return}
if(tab==='documents'){const rows=await toolRows('document');box.innerHTML=`<div class="toolGrid"><form class="card" id="docForm"><h3>Documentos e vouchers</h3><label>Tipo<select id="docType"><option>Passagem</option><option>Voucher</option><option>Seguro viagem</option><option>Ingresso</option><option>Reserva</option><option>Passaporte</option><option>Outro</option></select></label><label>Nome<input id="docName" required placeholder="Ex.: Seguro viagem Europa"></label><label>Arquivo<input id="docFile" type="file" accept="application/pdf,image/jpeg,image/png,.pdf,.jpg,.jpeg,.png" required></label><small class="muted">PDF, JPG ou PNG · máximo 8 MB. O arquivo será privado e vinculado somente a esta viagem.</small><label>Observações<textarea id="docNotes"></textarea></label><button class="primary" id="docSubmit">Enviar documento</button><p class="error" id="docMsg"></p></form><div><h3>Documentos</h3>${rows.map(x=>`<div class="listItem documentItem"><div><b>${esc(x.data.type)} · ${esc(x.data.name)}</b><span>${esc(x.data.filename||'')}${x.data.size?' · '+fmt(x.data.size/1024,0)+' KB':''}</span><span>${esc(x.data.notes||'')}</span></div><div class="itemActions documentActions">${x.data.storagePath?`<button type="button" class="quoteBtn" onclick="viewDocument(${x.id},'${esc(x.data.name).replace(/'/g,"&#39;")}','${esc(x.data.mime||"")}')">Visualizar</button>`:(x.data.url?`<a class="quoteBtn" target="_blank" rel="noopener" href="${esc(x.data.url)}">Abrir legado ↗</a>`:'')}<button class="editBtn" onclick="editTool(${x.id},'document')">Editar</button><button class="removeBtn" onclick="delTool(${x.id})">Remover</button></div></div>`).join('')||'<div class="empty">Nenhum documento.</div>'}</div></div>`;$('#docForm').onsubmit=async e=>{e.preventDefault();const f=$('#docFile').files?.[0],msg=$('#docMsg'),btn=$('#docSubmit');msg.textContent='';if(!f)return msg.textContent='Selecione um arquivo.';if(f.size>8*1024*1024)return msg.textContent='O arquivo deve ter no máximo 8 MB.';if(!['application/pdf','image/jpeg','image/png'].includes(f.type))return msg.textContent='Envie um arquivo PDF, JPG ou PNG.';btn.disabled=true;btn.textContent='Enviando…';try{const base64=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result).split(',')[1]||'');r.onerror=reject;r.readAsDataURL(f)});await api('/api/documents/upload',{method:'POST',body:JSON.stringify({trip_id:t.id,type:$('#docType').value,name:$('#docName').value,notes:$('#docNotes').value,filename:f.name,mime:f.type,base64})});await renderAdvancedPanel('documents')}catch(err){msg.textContent=err.message;btn.disabled=false;btn.textContent='Enviar documento'}};return}
if(tab==='expenses'){const rows=await toolRows('expense'),total=rows.reduce((a,x)=>a+Number(x.data.amount||0),0),companions=tripCompanions(t),people=[me?.name||'Usuário principal',...companions];box.innerHTML=`<div class="stats"><div class="card"><span>Despesas registradas</span><strong>${money(total)}</strong></div><div class="card"><span>Por viajante</span><strong>${money(total/Math.max(1,t.travelers))}</strong></div></div><div class="toolGrid"><form class="card" id="expForm"><h3>Registrar despesa</h3><label>Descrição<input id="eDesc" required></label><div class="row"><label>Valor<input id="eAmount" type="number" min="0" step="0.01" required></label><label>Moeda<select id="eCur"><option>BRL</option><option>${t.currency}</option><option>EUR</option><option>USD</option></select></label></div><label>Pago por<select id="ePaid">${people.map(n=>`<option>${esc(n)}</option>`).join('')}</select></label><label>Dividir entre</label><div class="splitPicker">${companions.map(n=>`<label><input type="checkbox" class="expenseSplit" value="${esc(n)}"> <span>${esc(n)}</span></label>`).join('')||'<span class="muted">Nenhum convidado disponível.</span>'}</div><button class="primary">Adicionar</button></form><div><h3>Divisão de despesas</h3>${rows.map(x=>`<div class="listItem expenseItem"><div><b>${esc(x.data.description)}</b><span>Pago por ${esc(x.data.paidBy||'—')}</span><span>Dividir: ${esc(x.data.split||'todos')}</span>${x.data.source==='budget'?'<small>Importada automaticamente do Orçamento</small>':''}</div><b>${x.data.currency==='BRL'?money(x.data.amount):fmt(x.data.amount)+' '+esc(x.data.currency)}</b><div class="itemActions"><button class="editBtn" onclick="editTool(${x.id},'expense')">Editar</button><button class="removeBtn" onclick="delTool(${x.id})">Remover</button></div></div>`).join('')||'<div class="empty">Nenhuma despesa.</div>'}</div></div>`;$('#expForm').onsubmit=e=>{e.preventDefault();const names=$$('.expenseSplit:checked').map(x=>x.value);addTool('expense',{description:$('#eDesc').value,amount:Number($('#eAmount').value),currency:$('#eCur').value,paidBy:$('#ePaid').value,split:names.join(', '),splitNames:names})};return}
if(tab==='travelers'){const rows=await toolRows('collaborator'),companions=tripCompanions(t),isOwner=!t.shared;let invites=[];if(isOwner){try{invites=await api('/api/trip-collaborations?trip_id='+t.id)}catch{}}const accepted=invites.filter(i=>i.status==='accepted'),pending=invites.filter(i=>i.status==='pending'),acceptedEmails=new Set(accepted.map(i=>String(i.invitee_email||'').toLowerCase())),manualRows=rows.filter(x=>!acceptedEmails.has(String(x.data.email||'').toLowerCase()));box.innerHTML=`<div class="toolGrid">${isOwner?`<form class="card" id="colForm"><h3>Viajantes e colaboração</h3><label>Nome<input id="coName" required></label><label>E-mail<input id="coEmail" type="email" required></label><label>Permissão<select id="coRole"><option value="view">Somente visualizar</option><option value="edit">Pode editar</option></select></label><button class="primary">Enviar convite</button><p class="muted">O viajante receberá um link seguro por e-mail. Se ainda não tiver uma conta, poderá criá-la antes de aceitar.</p></form>`:`<div class="card"><h3>Viagem compartilhada</h3><p class="muted">Você participa desta viagem como colaborador.</p></div>`}<div><h3>Participantes</h3><div class="listItem"><div><b>${esc(t.shared?'Titular da viagem':me?.name||'Usuário principal')}</b><span>Titular da viagem</span></div></div>${manualRows.map(x=>`<div class="listItem"><div><b>${esc(x.data.name)}</b><span>${esc(x.data.email||'')} · ${esc(x.data.role)}</span></div>${isOwner?`<div class="itemActions"><button class="editBtn" onclick="editTool(${x.id},'collaborator')">Editar</button><button class="removeBtn" onclick="delTool(${x.id})">Remover</button></div>`:''}</div>`).join('')}${accepted.map(i=>`<div class="listItem"><div><b>${esc(i.invitee_name||i.invitee_email)}</b><span>${esc(i.invitee_email)} · ${i.permission==='edit'?'Pode editar':'Somente visualizar'}</span></div>${isOwner?`<div class="itemActions"><button class="editBtn" onclick="editTripCollaborator(${i.id},'${i.permission}')">Editar</button><button class="removeBtn" onclick="removeTripCollaborator(${i.id})">Remover</button></div>`:''}</div>`).join('')||(!manualRows.length&&!companions.length?'<div class="empty">Nenhum acompanhante cadastrado.</div>':'')}${isOwner&&pending.length?`<h3 class="collabInviteTitle">Convites pendentes</h3>${pending.map(i=>`<div class="listItem"><div><b>${esc(i.invitee_name||i.invitee_email)}</b><span>${esc(i.invitee_email)} · ${i.permission==='edit'?'Pode editar':'Somente visualizar'} · Pendente</span></div><div class="itemActions"><button class="editBtn" onclick="resendTripInvite(${i.id})">Reenviar</button><button class="removeBtn" onclick="cancelTripInvite(${i.id})">Cancelar</button></div></div>`).join('')}`:''}</div></div>`;if(isOwner)$('#colForm').onsubmit=async e=>{e.preventDefault();const name=$('#coName').value,email=$('#coEmail').value,permission=$('#coRole').value;try{await api('/api/trip-collaborations/invite',{method:'POST',body:JSON.stringify({trip_id:t.id,name,email,permission})});showResultModal('Convite enviado',`Enviamos um convite para ${email}.`);await refreshTrip();await renderAdvancedPanel('travelers')}catch(err){showResultModal('Não foi possível enviar',err.message)}};return}
if(tab==='assistant'){let chat=[];box.innerHTML=`<div class="assistantBox card"><div class="assistantHeader"><div><span class="eyebrow">Assistente Ih, viajei!</span><h3>Pergunte sobre sua viagem</h3></div><button class="ghost mini" id="asClear">Limpar conversa</button></div><p class="muted">O assistente considera os dados cadastrados nesta viagem, como roteiro, orçamento, reservas, checklist e compras de moeda.</p><div id="asConversation" class="assistantConversation"><div class="assistantWelcome">Olá! Posso ajudar a organizar esta viagem com base no que você já cadastrou.</div></div><textarea id="asQ" rows="4" maxlength="1500" placeholder="Ex.: Quanto do meu orçamento já está comprometido com reservas?"></textarea><div class="assistantActions"><button class="primary" id="asAsk">Perguntar</button></div></div>`;
const out=$('#asConversation');
const bindAssistantCards=(ui)=>{out.querySelectorAll('.assistantSavePlace').forEach(b=>b.onclick=()=>{const x=ui?.places?.[Number(b.dataset.place)];if(x){$('#asQ').value=`Salve ${x.name}`;ask()}});out.querySelectorAll('.assistantAddRoute').forEach(b=>b.onclick=()=>{const x=ui?.places?.[Number(b.dataset.place)];if(x){$('#asQ').value=`Adicione ${x.name} ao meu roteiro`;ask()}})};
const appendAI=async(answer,ui)=>{const el=document.createElement('div');el.className='assistantMsg ai';el.innerHTML=`<div class="assistantText">${esc(answer).replace(/\n/g,'<br>')}</div>${assistantVisual(ui)}`;out.appendChild(el);if(ui){bindAssistantCards(ui);await renderAssistantPlacesMap(ui,el)}};
try{const saved=await api('/api/assistant-history?trip_id='+t.id);if(saved.length){out.innerHTML='';for(const m of saved){if(m.role==='user')out.insertAdjacentHTML('beforeend',`<div class="assistantMsg user">${esc(m.content)}</div>`);else await appendAI(m.content,m.ui)}chat=saved.slice(-8).map(m=>({role:m.role,content:m.content}));out.scrollTop=out.scrollHeight}}catch(e){console.warn('Histórico do Assistente indisponível',e)}
const ask=async()=>{const q=$('#asQ').value.trim(),btn=$('#asAsk');if(!q)return;out.insertAdjacentHTML('beforeend',`<div class="assistantMsg user">${esc(q)}</div>`);$('#asQ').value='';btn.disabled=true;btn.textContent='Pensando…';const wait=document.createElement('div');wait.className='assistantMsg ai waiting';wait.textContent='Consultando…';out.appendChild(wait);out.scrollTop=out.scrollHeight;try{const d=await api('/api/travel-assistant',{method:'POST',body:JSON.stringify({trip_id:t.id,question:q})});wait.remove();await appendAI(d.answer,d.ui);chat.push({role:'user',content:q},{role:'assistant',content:d.answer});chat=chat.slice(-8)}catch(e){wait.classList.remove('waiting');wait.classList.add('error');wait.textContent=e.message}finally{btn.disabled=false;btn.textContent='Perguntar';out.scrollTop=out.scrollHeight}};
$('#asAsk').onclick=ask;$('#asQ').addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();ask()}});$('#asClear').onclick=async()=>{if(!confirm('Limpar todo o histórico desta conversa?'))return;try{await api('/api/assistant-history',{method:'DELETE',body:JSON.stringify({trip_id:t.id})});chat=[];out.innerHTML='<div class="assistantWelcome">Conversa limpa. Posso ajudar a organizar esta viagem.</div>'}catch(e){alert(e.message)}};return}}
function parseAlertDecimal(v){const s=String(v??'').trim().replace(/\s/g,'').replace(/^R\$/i,'');if(!s)return null;let n;if(s.includes(',')&&s.includes('.'))n=Number(s.replace(/\./g,'').replace(',','.'));else if(s.includes(','))n=Number(s.replace(',','.'));else n=Number(s);return Number.isFinite(n)&&n>=0?n:null}function formatAlertBRL(v){const n=Number(v);if(!Number.isFinite(n))return 'R$ 0,00';const max=Math.abs(n)>0&&Math.abs(n)<0.01?4:2;return new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL',minimumFractionDigits:2,maximumFractionDigits:max}).format(n)}if($('#editPurchaseCurrency')&&$('#pCurrency'))$('#editPurchaseCurrency').innerHTML=$('#pCurrency').innerHTML;$('#purchaseForm').onsubmit=async e=>{e.preventDefault();await api('/api/purchases',{method:'POST',body:JSON.stringify({trip_id:$('#purchaseTrip').value,currency:$('#pCurrency').value,amount:$('#pAmount').value,total_brl:$('#pTotal').value,provider:$('#pProvider').value,purchased_at:$('#pDate').value})});e.target.reset();$('#pDate').value=new Date().toISOString().slice(0,10);loadDashboard()};$('#alertForm').onsubmit=async e=>{e.preventDefault();const threshold=parseAlertDecimal($('#aThreshold').value);if(threshold===null){alert('Informe um valor válido em reais. Ex.: 6,25');return}await api('/api/alerts',{method:'POST',body:JSON.stringify({currency:$('#aCurrency').value,kind:$('#aKind').value,threshold})});e.target.reset();loadDashboard()};let purchaseEditRows=[];async function editPurchase(id){try{purchaseEditRows=await api('/api/purchases');const p=purchaseEditRows.find(x=>Number(x.id)===Number(id));if(!p)throw new Error('Compra não encontrada.');$('#editPurchaseId').value=p.id;$('#editPurchaseCurrency').value=p.currency;$('#editPurchaseAmount').value=p.amount;$('#editPurchaseTotal').value=p.total_brl;$('#editPurchaseProvider').value=p.provider||'';$('#editPurchaseDate').value=String(p.purchased_at||'').slice(0,10);$('#editPurchaseMsg').textContent='';$('#editPurchaseDialog').showModal()}catch(e){alert(e.message)}}window.editPurchase=editPurchase;$('#editPurchaseClose').onclick=()=>$('#editPurchaseDialog').close();$('#editPurchaseDialog').addEventListener('click',e=>{if(e.target===$('#editPurchaseDialog'))$('#editPurchaseDialog').close()});$('#editPurchaseForm').onsubmit=async e=>{e.preventDefault();const id=Number($('#editPurchaseId').value),btn=e.submitter||e.target.querySelector('button[type=submit]');btn.disabled=true;$('#editPurchaseMsg').textContent='';try{await api('/api/purchases/'+id,{method:'PATCH',body:JSON.stringify({currency:$('#editPurchaseCurrency').value,amount:$('#editPurchaseAmount').value,total_brl:$('#editPurchaseTotal').value,provider:$('#editPurchaseProvider').value,purchased_at:$('#editPurchaseDate').value})});$('#editPurchaseDialog').close();await loadDashboard();if(currentTrip?.trip?.id){try{await refreshTrip()}catch{}}}catch(err){$('#editPurchaseMsg').textContent=err.message}finally{btn.disabled=false}};async function delTrip(id){if(confirm('Excluir esta viagem?')){await api('/api/trips/'+id,{method:'DELETE'});loadDashboard()}}async function delPurchase(id){if(!confirm('Excluir esta compra de moeda?'))return;await api('/api/purchases/'+id,{method:'DELETE'});loadDashboard()}async function delAlert(id){await api('/api/alerts/'+id,{method:'DELETE'});loadDashboard()}
