function populateTripCurrencies(){const sel=$('#tCurrency');if(!sel)return;const byCode=new Map();for(const x of COUNTRY_CURRENCIES){if(!byCode.has(x.currency))byCode.set(x.currency,x.currencyName)}const rows=[...byCode.entries()].sort((a,b)=>a[1].localeCompare(b[1],'pt-BR'));sel.innerHTML=rows.map(([code,name])=>`<option value="${esc(code)}">${esc(name)} - ${esc(code)}</option>`).join('');if(byCode.has('EUR'))sel.value='EUR'}function populateDashboardCurrencies(){const byCode=new Map();for(const x of COUNTRY_CURRENCIES){if(!byCode.has(x.currency))byCode.set(x.currency,x.currencyName)}const rows=[...byCode.entries()].sort((a,b)=>a[1].localeCompare(b[1],'pt-BR'));for(const id of ['pCurrency','aCurrency']){const sel=$('#'+id);if(!sel)continue;const current=sel.value||'EUR';sel.innerHTML=rows.map(([code,name])=>`<option value="${esc(code)}">${esc(name)} - ${esc(code)}</option>`).join('');sel.value=byCode.has(current)?current:'EUR'}}
function setupCurrencyExplorer(){const input=$('#currencyCountrySearch'),list=$('#currencyCountryList'),picker=$('#currencyPicker'),arrow=$('#currencyPickerArrow');if(!input||!list||!picker||input.dataset.ready)return;input.dataset.ready='1';const label=x=>`${x.country} — ${x.currency} · ${x.currencyName}`;let selected=null;const render=(query='')=>{const q=query.trim().toLocaleLowerCase('pt-BR');const rows=COUNTRY_CURRENCIES.filter(x=>!q||label(x).toLocaleLowerCase('pt-BR').includes(q)||x.currency.toLowerCase().includes(q));list.innerHTML=rows.map(x=>`<button type="button" class="currencyCountryOption" data-code="${esc(x.countryCode)}" role="option"><span>${esc(x.country)} — ${esc(x.currency)}</span><small>${esc(x.currencyName)}</small></button>`).join('')||'<div class="currencyNoResult">Nenhuma moeda encontrada.</div>'};const open=()=>{render(input===document.activeElement&&!input.dataset.justOpened?input.value:'');picker.classList.add('open');input.setAttribute('aria-expanded','true')};const close=()=>{picker.classList.remove('open');input.setAttribute('aria-expanded','false')};const choose=x=>{selected=x;input.value=label(x);input.dataset.justOpened='';close();loadCountryCurrency(x)};input.addEventListener('focus',()=>{input.dataset.justOpened='1';open();setTimeout(()=>{input.dataset.justOpened=''},0)});input.addEventListener('click',()=>{input.select();render('');open()});input.addEventListener('input',()=>{render(input.value);open()});input.addEventListener('keydown',e=>{if(e.key==='Escape')close();if(e.key==='Enter'){e.preventDefault();const first=list.querySelector('.currencyCountryOption');if(first)first.click()}});if(arrow)arrow.addEventListener('click',e=>{e.preventDefault();input.focus();input.select();render('');open()});list.addEventListener('click',e=>{const b=e.target.closest('.currencyCountryOption');if(!b)return;const x=COUNTRY_CURRENCIES.find(v=>v.countryCode===b.dataset.code);if(x)choose(x)});document.addEventListener('click',e=>{if(!picker.contains(e.target))close()});const usd=COUNTRY_CURRENCIES.find(x=>x.countryCode==='US'&&x.currency==='USD');if(usd)choose(usd)}
function currencyHistorySvg(points){if(!points?.length)return '<div class="empty">Sem histórico disponível.</div>';const w=1000,h=300,pad=44,vals=points.map(p=>Number(p.brl)),min=Math.min(...vals),max=Math.max(...vals),range=max-min||1;const xy=points.map((p,i)=>[pad+(i/(Math.max(1,points.length-1)))*(w-pad*2),pad+(1-(Number(p.brl)-min)/range)*(h-pad*2)]);const path=xy.map((p,i)=>(i?'L':'M')+p[0].toFixed(1)+' '+p[1].toFixed(1)).join(' ');const labels=[0,Math.floor((points.length-1)/2),points.length-1].filter((v,i,a)=>a.indexOf(v)===i);return `<svg class="currencyHistoryChart" viewBox="0 0 ${w} ${h}" role="img" aria-label="Histórico da moeda"><line x1="${pad}" y1="${h-pad}" x2="${w-pad}" y2="${h-pad}" class="chartAxis"/><line x1="${pad}" y1="${pad}" x2="${pad}" y2="${h-pad}" class="chartAxis"/><path d="${path}" class="chartLine"/><g class="currencyHoverLayer" aria-hidden="true"><line class="currencyHoverLine" x1="0" y1="${pad}" x2="0" y2="${h-pad}"/><g class="currencyTooltip"><rect width="178" height="62" rx="10"/><text class="currencyTooltipDate" x="14" y="24"></text><text class="currencyTooltipValue" x="14" y="47"></text></g></g>${xy.map((p,i)=>`<circle cx="${p[0]}" cy="${p[1]}" r="4" class="chartPoint" data-chart-index="${i}" data-chart-x="${p[0]}" data-chart-date="${brDate(points[i].date)}" data-chart-value="${Number(points[i].brl).toLocaleString('pt-BR',{minimumFractionDigits:4,maximumFractionDigits:4})}"/>`).join('')}${labels.map(i=>`<text x="${xy[i][0]}" y="${h-12}" text-anchor="middle">${brDate(points[i].date)}</text>`).join('')}<text x="${pad+6}" y="${pad-12}">R$ ${max.toLocaleString('pt-BR',{minimumFractionDigits:4,maximumFractionDigits:4})}</text><text x="${pad+6}" y="${h-pad-8}">R$ ${min.toLocaleString('pt-BR',{minimumFractionDigits:4,maximumFractionDigits:4})}</text></svg>`}
function setupCurrencyChartInteractions(root){const svg=root?.querySelector('.currencyHistoryChart');if(!svg)return;const layer=svg.querySelector('.currencyHoverLayer'),line=svg.querySelector('.currencyHoverLine'),tip=svg.querySelector('.currencyTooltip'),date=svg.querySelector('.currencyTooltipDate'),value=svg.querySelector('.currencyTooltipValue');svg.querySelectorAll('.chartPoint').forEach(point=>{point.addEventListener('mouseenter',()=>{const x=Number(point.dataset.chartX),tipX=Math.max(52,Math.min(770,x+12));line.setAttribute('x1',x);line.setAttribute('x2',x);tip.setAttribute('transform',`translate(${tipX} 54)`);date.textContent=point.dataset.chartDate;value.textContent=`R$ ${point.dataset.chartValue}`;layer.classList.add('visible');point.classList.add('active')});point.addEventListener('mouseleave',()=>{layer.classList.remove('visible');point.classList.remove('active')})})}
async function loadCountryCurrency(x){const box=$('#currencyCountryDetail');if(!box)return;box.innerHTML='<div class="empty">Carregando cotação e histórico reais…</div>';try{const d=await api('/api/rates/history?currency='+encodeURIComponent(x.currency)+'&days=90');const s=d.summary;box.innerHTML=`<div class="currencyDetailHead"><div><span class="currencyCountryName">${esc(x.country)} · ${esc(x.currencyName)} (${esc(x.currency)})</span><div class="currencyBigRate">R$ ${Number(s.current).toLocaleString('pt-BR',{minimumFractionDigits:4,maximumFractionDigits:4})}</div></div><div class="currencyRadar">Radar ${s.score}/100 · ${esc(s.label)}</div></div><div class="currencyStats"><span>Mínima <em>R$ ${s.min.toFixed(4)}</em></span><span>Média <em>R$ ${s.average.toFixed(4)}</em></span><span>Máxima <em>R$ ${s.max.toFixed(4)}</em></span><span>Período <em>${d.points.length} cotações</em></span></div><div class="currencyChartTitle">Histórico recente · até 90 dias</div>${currencyHistorySvg(d.points)}<small class="currencySource">Fonte: ${esc(d.source)}</small>`;setupCurrencyChartInteractions(box)}catch(e){box.innerHTML=`<div class="empty">Não foi possível obter histórico real de ${esc(x.currency)} neste momento. ${esc(e.message)}</div>`}}
async function loadRadar(c){const k=c.toLowerCase(),cap=k[0].toUpperCase()+k.slice(1),btn=document.querySelector(`[data-radar="${c}"]`),set=(id,value)=>{const el=$('#'+id);if(el)el.textContent=value};if(btn){btn.disabled=true;btn.textContent='Atualizando…'}try{const d=await api('/api/rates/history?currency='+c+'&days=30'),rate=`R$ ${Number(d.summary.current).toLocaleString('pt-BR',{minimumFractionDigits:4,maximumFractionDigits:4})}`,score=`Radar ${d.summary.score}/100 · ${d.summary.label}`,source=`30 dias: mín. R$ ${d.summary.min.toFixed(4)} · média R$ ${d.summary.average.toFixed(4)} · máx. R$ ${d.summary.max.toFixed(4)} · Fonte: ${d.source}`;set(k+'Rate',rate);set(k+'Score',score);set(k+'Source',source);set('home'+cap+'Rate',rate);set('home'+cap+'Score',score);set('home'+cap+'Source',source)}catch(e){set(k+'Rate','Indisponível');set(k+'Score','Radar indisponível');set(k+'Source',e.message);set('home'+cap+'Rate','Indisponível');set('home'+cap+'Score','Radar indisponível');set('home'+cap+'Source',e.message)}finally{if(btn){btn.disabled=false;btn.textContent='↻ Atualizar análise'}}}
async function loadVetInfo(currency='EUR'){const box=$('#vetInfo'),btn=$('#vetRefresh');if(!box)return;if(btn){btn.disabled=true;btn.textContent='Atualizando…'}box.innerHTML='<div class="empty">Consultando o Banco Central…</div>';try{const d=await api('/api/vet/reference?currency='+currency);const month=d.reference?`${d.reference.slice(0,2)}/${d.reference.slice(2)}`:'—';box.innerHTML=`<div class="vetToolbar"><div><b>${d.currency}/BRL · referência ${month}</b><small>Ranking histórico oficial do Banco Central</small></div><div class="currencySwitch"><button type="button" data-vet-currency="EUR" class="${d.currency==='EUR'?'active':''}">Euro</button><button type="button" data-vet-currency="USD" class="${d.currency==='USD'?'active':''}">Dólar</button></div></div><div class="vetTable"><div class="vetRow vetHeader"><span>Instituição</span><span>VET médio</span><span>Operações</span><span>Ação</span></div>${d.rows.map((x,i)=>`<div class="vetRow"><span><b>${i+1}. ${esc(x.institution)}</b></span><span>R$ ${Number(x.vet).toLocaleString('pt-BR',{minimumFractionDigits:4,maximumFractionDigits:4})}</span><span>${Number(x.operations).toLocaleString('pt-BR')}</span><span>${x.action_url?`<a class="quoteBtn" href="${esc(x.action_url)}" target="_blank" rel="noopener noreferrer">Consultar cotação ↗</a>`:`<a class="quoteBtn secondary" href="${esc(x.bcb_url||d.url)}" target="_blank" rel="noopener noreferrer">Ver instituição ↗</a>`}</span></div>`).join('')}</div><p class="vetNote">${esc(d.notice)}</p><a class="externalBtn" href="${esc(d.url)}" target="_blank" rel="noopener">Ver conjunto oficial no Banco Central ↗</a>`;box.querySelectorAll('[data-vet-currency]').forEach(x=>x.addEventListener('click',()=>loadVetInfo(x.dataset.vetCurrency)))}catch(e){box.innerHTML=`<div class="empty">${esc(e.message)}</div>`}finally{if(btn){btn.disabled=false;btn.textContent='↻ Atualizar dados'}}}
let adminUserRows=[];async function loadAdmin(){if(me?.role!=='admin')return;const [s,users,health,audit]=await Promise.all([api('/api/admin/stats').catch(e=>{console.error('[admin-stats]',e);return {users:0,trips:0,purchases:0,invested:0,plans:[],months:[]}}),api('/api/admin/users').catch(e=>{console.error('[admin-users]',e);return []}),api('/api/admin/health-integrations').catch(()=>null),api('/api/admin/audit-log').catch(()=>[])]);adminUserRows=users;if($('#adminHealth')&&health){$('#adminHealth').innerHTML=Object.entries(health.services||{}).map(([k,v])=>`<span class="healthItem ${v?'ok':'off'}"><b>${v?'✓':'○'}</b>${esc(k.replaceAll('_',' '))}</span>`).join('')}if($('#adminAudit'))$('#adminAudit').innerHTML=(audit||[]).slice(0,12).map(x=>`<div><b>${esc(x.action)}</b><span>${esc(x.target_type)} ${esc(x.target_id||'')} · ${esc(String(x.created_at||''))}</span></div>`).join('')||'<div class="empty">Nenhuma ação auditada ainda.</div>';if($('#adminMfaBtn')&&!$('#adminMfaBtn').dataset.bound){$('#adminMfaBtn').dataset.bound='1';$('#adminMfaBtn').onclick=async()=>{try{const z=await api('/api/admin/mfa/setup',{method:'POST',body:'{}'});const code=prompt(`Adicione esta chave ao seu aplicativo autenticador:\n\n${z.secret}\n\nDepois digite o código de 6 dígitos gerado:`);if(!code)return;await api('/api/admin/mfa/enable',{method:'POST',body:JSON.stringify({code})});alert('2FA administrativo ativado com sucesso.')}catch(e){alert(e.message)}}}$('#adminStats').innerHTML=[['Usuários',s.users],['Viagens cadastradas',s.trips],['Compras de moeda',s.purchases],['Total registrado',money(s.invested)]].map(([a,b])=>`<div class="card"><span>${a}</span><strong>${b}</strong></div>`).join('');const max=Math.max(1,...s.months.map(x=>x.users));$('#usersChart').innerHTML=s.months.length?s.months.map(x=>`<div class="barCol"><div class="barValue">${x.users}</div><i style="height:${Math.max(8,x.users/max*120)}px"></i><small>${monthLabel(x.month)}</small></div>`).join(''):'<div class="empty">Ainda não há histórico suficiente.</div>';const total=Math.max(1,s.plans.reduce((a,x)=>a+x.n,0));$('#plansChart').innerHTML=['gratuito','intermediario','pro'].map(plan=>{const row=s.plans.find(x=>x.plan===plan),n=row?.n||0;return `<div class="planBarRow"><div><b>${plan==='intermediario'?'Intermediário':plan==='pro'?'PRO':'Gratuito'}</b><span>${n} usuário(s)</span></div><div class="planTrack"><i style="width:${n/total*100}%"></i></div><strong>${Math.round(n/total*100)}%</strong></div>`}).join('');renderAdminUsers(users);const search=$('#adminUserSearch');if(search&&!search.dataset.bound){search.dataset.bound='1';search.addEventListener('input',()=>{const q=search.value.toLowerCase().trim();renderAdminUsers(adminUserRows.filter(u=>!q||u.name.toLowerCase().includes(q)||u.email.toLowerCase().includes(q)))})}}function monthLabel(v){const [y,m]=String(v).split('-');return `${m}/${String(y).slice(-2)}`}function renderAdminUsers(users){$('#adminUsers').innerHTML=users.length?`<div class="adminTable"><div class="adminRow adminRowHead"><span>Usuário</span><span>Plano</span><span>Cadastro</span><span>Viagens</span><span>Compras</span><span>Ações</span></div>${users.map(u=>`<div class="adminRow"><span><b>${esc(u.name)}</b><small>${esc(u.email)}</small></span><span><span class="planTag">${adminPlanName(u.effective_plan||u.plan)}</span>${u.test_plan?`<small class="adminTestPlan">Teste${u.test_plan_until?' até '+brDate(String(u.test_plan_until).slice(0,10)):' sem prazo'}</small>`:''}</span><span>${brDate(String(u.created_at).slice(0,10))}</span><span>${u.trips}</span><span>${u.purchases}</span><span class="adminUserActions"><button class="mini" onclick="adminViewUser(${u.id})">Visualizar</button><button class="mini" onclick="adminEditUser(${u.id})">Editar</button><button class="danger mini" onclick="adminDeleteUser(${u.id},'${esc(u.name).replace(/'/g,'&#39;')}')">Excluir</button></span></div>`).join('')}</div>`:'<div class="empty">Nenhum usuário encontrado.</div>'}
function adminPlanName(p){return p==='intermediario'?'Intermediário':p==='pro'?'PRO':'Gratuito'}
function adminUserById(id){return adminUserRows.find(x=>Number(x.id)===Number(id))}
function closeAdminUserDialog(){if($('#adminUserDialog')?.open)$('#adminUserDialog').close()}
async function adminEditUser(id){const u=adminUserById(id);if(!u)return;$('#adminUserDialogTitle').textContent='Editar usuário';$('#adminUserDialogBody').innerHTML=`<form id="adminUserEditForm" class="adminUserEditForm"><label>Nome<input id="adminEditName" required maxlength="100" value="${esc(u.name)}"></label><label>E-mail<input id="adminEditEmail" required type="email" maxlength="180" value="${esc(u.email)}"></label><div class="adminTestAccessBox"><b>Plano comercial: ${adminPlanName(u.plan)}</b><span>O Mercado Pago continua sendo a fonte da assinatura comercial.</span><label>Acesso de teste<select id="adminTestPlan"><option value="">Sem override</option><option value="gratuito" ${u.test_plan==='gratuito'?'selected':''}>Gratuito</option><option value="intermediario" ${u.test_plan==='intermediario'?'selected':''}>Intermediário</option><option value="pro" ${u.test_plan==='pro'?'selected':''}>PRO</option></select></label><label>Validade<select id="adminTestDays"><option value="1">1 dia</option><option value="7">7 dias</option><option value="30" selected>30 dias</option><option value="">Sem prazo</option></select></label><button type="button" class="primary adminTestApply" id="adminApplyTestPlan">Aplicar acesso de teste</button>${u.test_plan?'<button type="button" class="danger adminTestRemove" id="adminRemoveTestPlan">Remover acesso de teste</button>':''}</div><p id="adminUserEditMsg" class="error"></p><div class="actions"><button type="button" id="adminUserEditCancel">Cancelar</button><button type="submit" class="primary">Salvar alterações</button></div></form>`;$('#adminUserDialog').showModal();$('#adminUserEditCancel').onclick=closeAdminUserDialog;$('#adminApplyTestPlan').onclick=async()=>{const plan=$('#adminTestPlan').value;if(!plan){$('#adminUserEditMsg').textContent='Selecione um plano de teste.';return}try{const v=$('#adminTestDays').value;await api('/api/admin/users/'+id+'/test-plan',{method:'POST',body:JSON.stringify({plan,days:v===''?null:Number(v)})});closeAdminUserDialog();await loadAdmin();alert('Acesso de teste '+adminPlanName(plan)+' aplicado.')}catch(err){$('#adminUserEditMsg').textContent=err.message}};if($('#adminRemoveTestPlan'))$('#adminRemoveTestPlan').onclick=async()=>{try{await api('/api/admin/users/'+id+'/test-plan',{method:'DELETE'});closeAdminUserDialog();await loadAdmin();alert('Acesso de teste removido.')}catch(err){$('#adminUserEditMsg').textContent=err.message}};$('#adminUserEditForm').onsubmit=async e=>{e.preventDefault();try{await api('/api/admin/users/'+id,{method:'PATCH',body:JSON.stringify({name:$('#adminEditName').value,email:$('#adminEditEmail').value})});closeAdminUserDialog();await loadAdmin()}catch(err){$('#adminUserEditMsg').textContent=err.message}}}
function adminDataList(title,rows,render){if(!rows?.length)return '';return `<section class="adminUserDataSection"><h4>${title} <small>${rows.length}</small></h4><div class="adminUserDataList">${rows.map(render).join('')}</div></section>`}
async function adminViewUser(id){try{const d=await api('/api/admin/users/'+id),a=d.account;$('#adminUserDialogTitle').textContent='Visualizar usuário';$('#adminUserDialogBody').innerHTML=`<div class="adminUserSummary"><div><span>Nome</span><strong>${esc(a.name)}</strong></div><div><span>E-mail</span><strong>${esc(a.email)}</strong></div><div><span>Plano comercial</span><strong>${adminPlanName(a.plan)}</strong></div><div><span>Acesso efetivo</span><strong>${adminPlanName(a.test_plan||a.plan)}${a.test_plan?' · teste':''}</strong></div><div><span>Cadastro</span><strong>${brDate(String(a.created_at).slice(0,10))}</strong></div></div>${adminDataList('Alertas',d.alerts,x=>`<div><b>${esc(x.currency)}</b><span>${x.kind==='below'?'Abaixo':'Acima'} de R$ ${Number(x.threshold).toFixed(4)}</span></div>`)}<div class="adminUserTrips">${d.trips.length?d.trips.map(t=>`<details class="adminUserTrip"><summary><div><strong>${esc(t.name)}</strong><small>${esc(t.destinations)||'Destinos não informados'} · ${t.travelers} viajante(s)</small></div><span>⌄</span></summary><div class="adminTripDetails"><div class="adminTripFacts"><span>Período <b>${t.start_date?brDate(t.start_date):'—'} a ${t.end_date?brDate(t.end_date):'—'}</b></span><span>Perfil <b>${esc(t.profile)}</b></span><span>Moeda/meta <b>${esc(t.currency)} ${fmt(t.target_amount)}</b></span><span>Acompanhantes <b>${(t.companions||[]).map(esc).join(', ')||'—'}</b></span></div>${adminDataList('Compras de moeda',t.purchases,x=>`<div><b>${fmt(x.amount)} ${esc(x.currency)}</b><span>${money(x.total_brl)} · ${esc(x.provider)||'Instituição não informada'} · ${brDate(x.purchased_at)}</span></div>`)}${adminDataList('Orçamento',t.budget,x=>`<div><b>${esc(x.category)} · ${money(x.amount)}</b><span>${esc(x.city||x.country||'')} ${x.description?'· '+esc(x.description):''}</span></div>`)}${adminDataList('Roteiro',t.itinerary,x=>`<div><b>${x.item_date?brDate(x.item_date)+' · ':''}${esc(x.title)}</b><span>${esc(x.location||'')}${x.notes?' · '+esc(x.notes):''}</span></div>`)}${adminDataList('Reservas',t.reservations,x=>`<div><b>${esc(x.kind)} · ${esc(x.provider||'Fornecedor não informado')}</b><span>${money(x.amount_brl)} · ${esc(x.status)}${x.confirmation?' · '+esc(x.confirmation):''}</span></div>`)}${adminDataList('Checklist',t.checklist,x=>`<div><b>${x.done?'✓':'○'} ${esc(x.title)}</b></div>`)}${adminDataList('Documentos, despesas, viajantes e outros dados',t.tools.filter(x=>x.type!=='route_choice'),x=>{const z=x.data||{};return `<div><b>${x.type==='document'?'Documento':x.type==='expense'?'Despesa':x.type==='collaborator'?'Viajante':x.type==='place'?'Lugar salvo':esc(x.type)}</b><span>${esc(z.name||z.title||z.filename||z.description||z.email||'Item cadastrado')}</span></div>`})}</div></details>`).join(''):'<div class="empty">Este usuário ainda não possui viagens cadastradas.</div>'}</div>`;$('#adminUserDialog').showModal()}catch(e){alert(e.message)}}
async function adminDeleteUser(id,name){if(!confirm(`Excluir o usuário ${name} e todos os dados vinculados?`))return;try{await api('/api/admin/users/'+id,{method:'DELETE'});await loadAdmin()}catch(e){alert(e.message)}}

let billingCardForm=null,billingSelection=null;
async function openBillingCheckout(plan,cycle='monthly'){
 if(!me)return openAuth('login');
 const data=await api('/api/plans'); const p=data.plans.find(x=>x.id===plan);
 if(!p)throw new Error('Plano não encontrado.');
 if(!data.publicKey)throw new Error('Checkout ainda não configurado. Cadastre MERCADOPAGO_PUBLIC_KEY no Railway.');
 if(!window.MercadoPago)throw new Error('Não foi possível carregar o checkout seguro. Tente novamente.');
 const amount=cycle==='annual'?p.annual:p.monthly; billingSelection={plan,cycle,amount};
 $('#billingCheckoutSummary').textContent=`Plano ${p.name} · ${cycle==='annual'?money(amount)+'/ano':money(amount)+'/mês'}`;
 $('#billingCheckoutMsg').textContent=''; $('#form-checkout__cardholderEmail').value=me.email||'';
 const dlg=$('#billingCheckoutDialog'); if(!dlg.open)dlg.showModal();
 try{if(billingCardForm&&billingCardForm.unmount)billingCardForm.unmount()}catch{}
 const mp=new MercadoPago(data.publicKey,{locale:'pt-BR'});
 billingCardForm=mp.cardForm({amount:String(amount),iframe:true,form:{id:'form-checkout',cardNumber:{id:'form-checkout__cardNumber',placeholder:'Número do cartão'},expirationDate:{id:'form-checkout__expirationDate',placeholder:'MM/AA'},securityCode:{id:'form-checkout__securityCode',placeholder:'CVV'},cardholderName:{id:'form-checkout__cardholderName',placeholder:'Nome do titular'},issuer:{id:'form-checkout__issuer'},installments:{id:'form-checkout__installments'},identificationType:{id:'form-checkout__identificationType'},identificationNumber:{id:'form-checkout__identificationNumber',placeholder:'CPF'},cardholderEmail:{id:'form-checkout__cardholderEmail',placeholder:'E-mail'}},callbacks:{onFormMounted:error=>{if(error)$('#billingCheckoutMsg').textContent='Não foi possível iniciar o formulário seguro.'},onSubmit:async event=>{event.preventDefault();const btn=$('#form-checkout__submit');btn.disabled=true;$('#billingCheckoutMsg').textContent='';try{const d=billingCardForm.getCardFormData();if(!d.token)throw new Error('Confira os dados do cartão.');const r=await api('/api/plans/select',{method:'POST',body:JSON.stringify({plan:billingSelection.plan,billing_cycle:billingSelection.cycle,card_token_id:d.token})});me=await api('/api/me');syncNav();dlg.close();showResultModal(r.status==='authorized'?'Assinatura ativada':'Assinatura recebida',r.status==='authorized'?`Seu plano ${p.name} já está ativo.`:'Estamos confirmando a autorização da assinatura.');}catch(e){$('#billingCheckoutMsg').textContent=e.message}finally{btn.disabled=false}},onFetching:()=>{const pr=$('.billingProgress');pr.removeAttribute('value');return()=>pr.setAttribute('value','0')}}});
}
$('#billingCheckoutClose').onclick=()=>$('#billingCheckoutDialog').close();$('#billingCheckoutDialog').addEventListener('click',e=>{if(e.target===$('#billingCheckoutDialog'))$('#billingCheckoutDialog').close()});
function bindPlanButtons(){document.querySelectorAll('.planBtn').forEach(btn=>btn.addEventListener('click',async()=>{const plan=btn.dataset.plan;if(!me){openAuth('register');return}if(me.role==='admin'){alert('Planos são destinados às contas de viajantes.');return}try{if(plan==='gratuito'){await api('/api/plans/select',{method:'POST',body:JSON.stringify({plan})});me=await api('/api/me');alert('Plano Gratuito selecionado.');return}await openBillingCheckout(plan,'monthly')}catch(e){alert(e.message)}}));const c=$('#ctaStart');if(c)c.onclick=()=>{if(authenticatedCta())return;openAuth('register')}}bindPlanButtons();populateDashboardCurrencies();setupCurrencyExplorer();document.querySelectorAll('[data-radar]').forEach(b=>b.addEventListener('click',()=>loadRadar(b.dataset.radar)));const vetRefresh=$('#vetRefresh');if(vetRefresh)vetRefresh.addEventListener('click',()=>loadVetInfo());Object.assign(window,{openTrip,delTrip,delAlert,delItem,delTool,editItem,editTool,viewDocument,toggleCheck,loadRadar,loadVetInfo,adminViewUser,adminEditUser,adminDeleteUser});init().finally(()=>document.documentElement.classList.remove('restoringView'));

