let travelGuides=[],guideDraftSections=[];
function guideDateBR(v){if(!v)return '';const [y,m,d]=v.split('-');return `${d}/${m}/${y}`}
function localISODate(){const d=new Date(),pad=n=>String(n).padStart(2,'0');return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`}
async function imageFileToDataUrl(file){if(!file)return '';if(!/^image\/(jpeg|png|webp)$/.test(file.type))throw new Error('Envie uma imagem JPG, PNG ou WebP.');if(file.size>8*1024*1024)throw new Error('A imagem deve ter no máximo 8 MB.');const raw=await new Promise((ok,no)=>{const r=new FileReader();r.onload=()=>ok(r.result);r.onerror=()=>no(new Error('Não foi possível ler a imagem.'));r.readAsDataURL(file)});return await new Promise((ok,no)=>{const im=new Image();im.onload=()=>{const max=1600,scale=Math.min(1,max/Math.max(im.width,im.height)),c=document.createElement('canvas');c.width=Math.max(1,Math.round(im.width*scale));c.height=Math.max(1,Math.round(im.height*scale));c.getContext('2d').drawImage(im,0,0,c.width,c.height);ok(c.toDataURL('image/jpeg',.82))};im.onerror=()=>no(new Error('Imagem inválida.'));im.src=raw})}
async function loadGuides(){try{travelGuides=await api('/api/guides');renderGuideGrid(travelGuides)}catch(e){$('#guideGrid').innerHTML=`<div class="empty">${esc(e.message)}</div>`}}
function renderGuideGrid(rows){const q=($('#guideSearch')?.value||'').trim().toLowerCase();const list=(rows||[]).filter(g=>!q||`${g.title} ${g.destination}`.toLowerCase().includes(q)).slice(0,12);$('#guideGrid').innerHTML=list.length?list.map(g=>`<article class="guideTile" data-guide-id="${g.id}" tabindex="0"><div class="guideTileImage"><img src="${esc(g.hero_image)}" alt="${esc(g.destination)}"></div><div class="guideTileBody"><span>${esc(g.destination)}</span><h3>${esc(g.title)}</h3><p>${esc(g.intro).slice(0,115)}${g.intro.length>115?'…':''}</p><small>${guideDateBR(g.published_at)}</small></div></article>`).join(''):'<div class="empty">Nenhum guia encontrado.</div>';$$('.guideTile').forEach(x=>{const open=()=>openGuide(Number(x.dataset.guideId));x.onclick=open;x.onkeydown=e=>{if(e.key==='Enter')open()}})}
async function openGuide(id){try{const g=await api('/api/guides/'+id);show('guideDetail');window.scrollTo(0,0);$('#guideDetailContent').innerHTML=`<section class="guideHero"><img src="${esc(g.hero_image)}" alt="${esc(g.destination)}"><div class="guideHeroShade"></div><div class="guideHeroText"><span>${esc(g.destination)}</span><h1>${esc(g.title)}</h1></div></section><div class="guideArticle"><div class="guideMeta">Publicado em ${guideDateBR(g.published_at)}</div><p class="guideIntro">${esc(g.intro).replace(/\n/g,'<br>')}</p><div class="guideSections">${(g.sections||[]).map((s,i)=>`<details class="guideSection" ${i===0?'open':''}><summary><div><h2>${esc(s.title)}</h2><small>${(s.cards||[]).length} ${((s.cards||[]).length===1?'lugar':'lugares')}</small></div><span>⌄</span></summary><div class="guideCards">${(s.cards||[]).map((c,n)=>`<article class="guidePlaceCard"><div class="guidePlaceCopy"><div class="guidePlaceTitle"><span>${n+1}</span><h3>${esc(c.name)}</h3></div>${c.price?`<div class="guidePrice">${esc(c.price)}</div>`:''}<p>${esc(c.description)}</p></div><div class="guidePlacePhoto">${c.image?`<img src="${esc(c.image)}" alt="${esc(c.name)}">`:''}</div></article>`).join('')}</div></details>`).join('')}</div></div>`}catch(e){alert(e.message)}}
$('#guideSearch').oninput=()=>renderGuideGrid(travelGuides);
function renderGuideBuilder(){const host=$('#guideSectionsBuilder');host.innerHTML=guideDraftSections.length?guideDraftSections.map((sec,si)=>`<section class="guideSectionEditor"><div class="guideSectionEditorHead"><label>Nome da seção<input class="guideSectionTitle" data-si="${si}" value="${esc(sec.title)}" placeholder="Ex.: Portugal • Restaurantes"></label><button type="button" class="removeGuideSection" data-si="${si}">Remover seção</button></div><div class="guideDraftCards">${(sec.cards||[]).map((c,ci)=>`<article class="guideDraftCard"><div>${c.image?`<img src="${esc(c.image)}" alt="">`:''}</div><div><strong>${esc(c.name)}</strong><span>${esc(c.price)}</span><p>${esc(c.description)}</p></div><button type="button" class="removeGuideCard" data-si="${si}" data-ci="${ci}">Remover</button></article>`).join('')}</div><div class="guideCardEditor"><h4>Adicionar card</h4><label>Nome do lugar<input class="newCardName" data-si="${si}" maxlength="140" placeholder="Nome do lugar"></label><label>Imagem do local<input class="newCardImage" data-si="${si}" type="file" accept="image/jpeg,image/png,image/webp"></label><label>Descrição<textarea class="newCardDescription" data-si="${si}" rows="3" maxlength="2000"></textarea></label><label>Preço<select class="newCardPrice" data-si="${si}"><option value="$">$</option><option value="$$" selected>$$</option><option value="$$$">$$$</option><option value="$$$$">$$$$</option></select></label><button type="button" class="primary addGuideCard" data-si="${si}">Adicionar card à seção</button></div></section>`).join(''):'<div class="empty">Adicione a primeira seção do guia.</div>';
  $$('.guideSectionTitle').forEach(x=>x.oninput=()=>guideDraftSections[+x.dataset.si].title=x.value);$$('.removeGuideSection').forEach(x=>x.onclick=()=>{guideDraftSections.splice(+x.dataset.si,1);renderGuideBuilder()});$$('.removeGuideCard').forEach(x=>x.onclick=()=>{guideDraftSections[+x.dataset.si].cards.splice(+x.dataset.ci,1);renderGuideBuilder()});$$('.addGuideCard').forEach(x=>x.onclick=async()=>{const si=+x.dataset.si,name=$(`.newCardName[data-si="${si}"]`).value.trim(),desc=$(`.newCardDescription[data-si="${si}"]`).value.trim(),price=$(`.newCardPrice[data-si="${si}"]`).value,file=$(`.newCardImage[data-si="${si}"]`).files[0];if(!name||!desc||!file){$('#guideMsg').textContent='Preencha Nome do lugar, Imagem do local e Descrição antes de adicionar o card.';return}try{x.disabled=true;const image=await imageFileToDataUrl(file);guideDraftSections[si].cards.push({name,image,description:desc,price});$('#guideMsg').textContent='';renderGuideBuilder()}catch(e){$('#guideMsg').textContent=e.message}finally{x.disabled=false}})}
function openGuideAdmin(g=null){$('#guideForm').reset();$('#guideId').value=g?.id||'';$('#guideDestination').value=g?.destination||'';$('#guideTitle').value=g?.title||'';$('#guideHero').value=g?.hero_image||'';$('#guideIntro').value=g?.intro||'';$('#guideDate').value=g?.published_at||localISODate();$('#guideDateLabel').textContent=guideDateBR($('#guideDate').value);$('#guideHeroName').textContent=g?.hero_image?'Imagem de capa atual carregada.':'Nenhuma imagem selecionada.';$('#guideHeroPreview').classList.toggle('hidden',!g?.hero_image);if(g?.hero_image)$('#guideHeroPreview').src=g.hero_image;guideDraftSections=structuredClone(g?.sections||[]);$('#guideMsg').textContent='';$('#guideDialogTitle').textContent=g?'Editar Guia de viagem':'Cadastrar Guia de viagem';renderGuideBuilder();$('#guideDialog').showModal()}
const adminCreate=$('.adminCreate');
if(adminCreate){adminCreate.onmouseenter=()=>adminCreate.classList.add('open');adminCreate.onmouseleave=()=>adminCreate.classList.remove('open')}
$('#adminCreateBtn').onclick=e=>{e.preventDefault();e.stopPropagation()};
document.addEventListener('click',e=>{const menu=$('.adminCreate');if(menu&&!menu.contains(e.target))menu.classList.remove('open')});
$('#adminGuideBtn').onclick=e=>{e.stopPropagation();$('.adminCreate').classList.remove('open');openGuideAdmin()};
$('#addGuideSection').onclick=()=>{guideDraftSections.push({title:'',cards:[]});renderGuideBuilder()};
$('#guideHeroFile').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;const data=await imageFileToDataUrl(f);$('#guideHero').value=data;$('#guideHeroName').textContent=f.name;$('#guideHeroPreview').src=data;$('#guideHeroPreview').classList.remove('hidden');$('#guideMsg').textContent=''}catch(err){e.target.value='';$('#guideMsg').textContent=err.message}};
async function loadAdminGuides(){if(me?.role!=='admin'||!$('#adminGuides'))return;try{const rows=await api('/api/guides');$('#adminGuides').innerHTML=rows.length?rows.map(g=>`<div class="adminGuideRow"><div class="adminGuideInfo"><img class="adminGuideThumb" src="${esc(g.hero_image)}" alt=""><div><strong>${esc(g.title)}</strong><small>${esc(g.destination)} · ${guideDateBR(g.published_at)}</small></div></div><div><button class="editGuide" data-id="${g.id}">Editar</button><button class="removeGuide" data-id="${g.id}">Remover</button></div></div>`).join(''):'<div class="empty">Nenhum guia publicado.</div>';$$('.editGuide').forEach(b=>b.onclick=async()=>openGuideAdmin(await api('/api/guides/'+b.dataset.id)));$$('.removeGuide').forEach(b=>b.onclick=async()=>{if(!confirm('Remover este guia de viagem?'))return;await api('/api/admin/guides/'+b.dataset.id,{method:'DELETE'});loadAdminGuides()})}catch(e){$('#adminGuides').innerHTML=`<div class="empty">${esc(e.message)}</div>`}}
function closeGuideDialog(){if($('#guideDialog').open)$('#guideDialog').close()}
$('#guideCancel').onclick=closeGuideDialog;$('#guideClose').onclick=closeGuideDialog;$('#guideDialog').addEventListener('click',e=>{if(e.target===$('#guideDialog'))closeGuideDialog()});
$('#guideForm').onsubmit=async e=>{e.preventDefault();try{const destination=$('#guideDestination').value.trim(),title=$('#guideTitle').value.trim(),hero=$('#guideHero').value,intro=$('#guideIntro').value.trim();if(!destination||!title||!hero||!intro)throw new Error('Preencha Destino, Título, Imagem de capa e Texto de apresentação.');if(!guideDraftSections.length)throw new Error('Adicione pelo menos uma seção.');for(const s of guideDraftSections){if(!s.title.trim())throw new Error('Informe o nome de todas as seções.');if(!s.cards.length)throw new Error(`Adicione pelo menos um card na seção “${s.title}”.`)}const payload={title,destination,hero_image:hero,intro,published_at:$('#guideDate').value||localISODate(),sections:guideDraftSections};const id=$('#guideId').value;const saved=await api(id?'/api/admin/guides/'+id:'/api/admin/guides',{method:id?'PUT':'POST',body:JSON.stringify(payload)});closeGuideDialog();await loadAdminGuides();travelGuides=await api('/api/guides');renderGuideGrid(travelGuides);alert(id?'Guia atualizado com sucesso.':'Guia publicado com sucesso.')}catch(err){$('#guideMsg').textContent=err.message}};


if($('#adminUserClose'))$('#adminUserClose').onclick=closeAdminUserDialog;if($('#adminUserDialog'))$('#adminUserDialog').addEventListener('click',e=>{if(e.target===$('#adminUserDialog'))closeAdminUserDialog()});

