// v74 — contato e suporte
const supportDialog=$('#supportDialog'),supportForm=$('#supportForm'),footerSupport=$('#footerSupport'),resultDialog=$('#resultDialog');
function editTripCollaborator(id,currentPermission){openEditModal('Editar permissão',editField('Permissão',`<select id="acceptedCollabPermission"><option value="view" ${currentPermission==='view'?'selected':''}>Somente visualizar</option><option value="edit" ${currentPermission==='edit'?'selected':''}>Pode editar</option></select>`),async()=>{await api('/api/trip-collaborations/update',{method:'POST',body:JSON.stringify({id,permission:$('#acceptedCollabPermission').value})});await refreshTrip();await renderAdvancedPanel('travelers')})}
async function removeTripCollaborator(id){if(!confirm('Deseja remover este participante da viagem? Ele perderá imediatamente o acesso à viagem.'))return;try{await api('/api/trip-collaborations/remove',{method:'POST',body:JSON.stringify({id})});showResultModal('Participante removido','O compartilhamento foi encerrado e este participante não tem mais acesso à viagem.');await refreshTrip();await renderAdvancedPanel('travelers')}catch(e){showResultModal('Não foi possível remover',e.message)}}
async function resendTripInvite(id){try{await api('/api/trip-collaborations/resend',{method:'POST',body:JSON.stringify({id})});showResultModal('Convite reenviado','Um novo link de convite foi enviado. O link anterior deixou de ser válido.');await renderAdvancedPanel('travelers')}catch(e){showResultModal('Não foi possível reenviar',e.message)}}
async function cancelTripInvite(id){if(!confirm('Deseja cancelar este convite pendente? O link enviado anteriormente deixará de funcionar.'))return;try{await api('/api/trip-collaborations/cancel',{method:'POST',body:JSON.stringify({id})});showResultModal('Convite cancelado','O convite foi cancelado e o link anterior não pode mais ser utilizado.');await renderAdvancedPanel('travelers')}catch(e){showResultModal('Não foi possível cancelar',e.message)}}
function showResultModal(title,message){$('#resultDialogTitle').textContent=title;$('#resultDialogMessage').textContent=message;if(!resultDialog.open)resultDialog.showModal()}
if($('#resultDialogClose'))$('#resultDialogClose').onclick=()=>resultDialog.close();if($('#resultDialogOk'))$('#resultDialogOk').onclick=()=>resultDialog.close();if(resultDialog)resultDialog.addEventListener('click',e=>{if(e.target===resultDialog)resultDialog.close()});
function openSupport(){if(me){$('#supportName').value=me.name||'';$('#supportEmail').value=me.email||''}if(!supportDialog.open)supportDialog.showModal()}
if(footerSupport)footerSupport.onclick=openSupport;
if($('#supportClose'))$('#supportClose').onclick=()=>supportDialog.close();
if(supportDialog)supportDialog.addEventListener('click',e=>{if(e.target===supportDialog)supportDialog.close()});
if(supportForm)supportForm.onsubmit=async e=>{e.preventDefault();const btn=$('#supportSubmit');btn.disabled=true;try{await api('/api/support',{method:'POST',body:JSON.stringify({name:$('#supportName').value,phone:$('#supportPhone').value,email:$('#supportEmail').value,subject:$('#supportSubject').value,message:$('#supportMessage').value})});supportForm.reset();if(me){$('#supportName').value=me.name||'';$('#supportEmail').value=me.email||''}supportDialog.close();showResultModal('Mensagem enviada','Sua mensagem foi enviada com sucesso para a equipe do Ih, viajei!.')}catch(err){supportDialog.close();showResultModal('Não foi possível enviar',err.message)}finally{btn.disabled=false}};

let notificationTimer=null;
function notificationWhen(v){try{const d=new Date(String(v).replace(' ','T')+'Z'),sec=Math.max(0,(Date.now()-d.getTime())/1000);if(sec<60)return 'Agora';if(sec<3600)return `Há ${Math.floor(sec/60)} min`;if(sec<86400)return `Há ${Math.floor(sec/3600)} h`;return d.toLocaleDateString('pt-BR')}catch{return ''}}
async function loadNotifications(){if(!me||me.role==='admin')return;const d=await api('/api/notifications');const badge=$('#notificationBadge'),list=$('#notificationList');if(!badge||!list)return;badge.textContent=String(d.unread||0);badge.classList.toggle('hidden',!(d.unread>0));list.innerHTML=(d.rows||[]).map(n=>`<button type="button" class="notificationItem ${n.is_read?'':'unread'}" data-notification-id="${n.id}" data-trip-id="${n.trip_id||''}" data-tab="${esc(n.target_tab||'overview')}"><span class="notificationTitle">${esc(n.title)}</span><span class="notificationMessage">${esc(n.message)}</span><small>${notificationWhen(n.created_at)}</small></button>`).join('')||'<div class="notificationEmpty">Nenhuma notificação.</div>';list.querySelectorAll('.notificationItem').forEach(x=>x.onclick=async()=>{try{await api(`/api/notifications/${x.dataset.notificationId}/read`,{method:'POST',body:'{}'});$('#notificationPanel').classList.remove('open');if(x.dataset.tripId)await openTrip(Number(x.dataset.tripId),x.dataset.tab||'overview');else show('dashboard');await loadNotifications()}catch(e){console.error(e)}})}
const notificationBtn=$('#notificationBtn'),notificationPanel=$('#notificationPanel'),notificationWrap=notificationBtn?.closest('.notificationWrap');if(notificationBtn){let notificationCloseTimer=null;const openNotifications=()=>{clearTimeout(notificationCloseTimer);notificationPanel.classList.add('open');loadNotifications().catch(()=>{})};const closeNotifications=()=>{clearTimeout(notificationCloseTimer);notificationCloseTimer=setTimeout(()=>notificationPanel.classList.remove('open'),180)};notificationBtn.onclick=e=>{e.stopPropagation();notificationPanel.classList.toggle('open');if(notificationPanel.classList.contains('open'))loadNotifications().catch(()=>{})};if(notificationWrap&&window.matchMedia('(hover: hover) and (pointer: fine)').matches){notificationBtn.addEventListener('mouseenter',openNotifications);notificationWrap.addEventListener('mouseenter',()=>clearTimeout(notificationCloseTimer));notificationWrap.addEventListener('mouseleave',closeNotifications);notificationPanel.addEventListener('mouseenter',openNotifications);notificationPanel.addEventListener('mouseleave',closeNotifications)}$('#notificationReadAll').onclick=async e=>{e.stopPropagation();await api('/api/notifications/read-all',{method:'POST',body:'{}'});await loadNotifications()};document.addEventListener('click',e=>{if(!e.target.closest('.notificationWrap'))closeNotifications()});notificationTimer=setInterval(()=>{if(me&&me.role!=='admin')loadNotifications().catch(()=>{})},45000)}

function urlBase64ToUint8Array(base64String){const padding='='.repeat((4-base64String.length%4)%4),base64=(base64String+padding).replace(/-/g,'+').replace(/_/g,'/'),raw=atob(base64);return Uint8Array.from([...raw].map(c=>c.charCodeAt(0)))}
if('serviceWorker'in navigator)window.addEventListener('load',()=>{navigator.serviceWorker.register('/sw-v153.js',{updateViaCache:'none'}).catch(e=>console.warn('PWA',e.message))},{once:true});

function assistantProposalCard(ui){if(!ui||ui.type!=='action_proposal')return '';return `<div class="assistantProposal"><b>Alteração proposta</b><span>${esc(ui.label||'')}</span><button type="button" class="primary" onclick="applyAssistantProposal(${Number(ui.proposal_id)})">Aplicar alteração</button></div>`}
async function applyAssistantProposal(id){try{await api('/api/assistant-proposals/'+id+'/apply',{method:'POST',body:'{}'});showResultModal('Alteração aplicada','O Assistente IA atualizou sua viagem somente após sua confirmação.');await refreshTrip()}catch(e){alert(e.message)}}
